package com.fairyringorganizer;

import java.awt.Color;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;

/** Parses optional per-code colours used only to restyle text on existing Favourites entries. */
public class FairyRingColorService
{
    private static final Map<String, Color> NAMED_COLORS;

    static
    {
        Map<String, Color> colors = new HashMap<>();
        colors.put("red", new Color(0xFF0000));
        colors.put("blue", new Color(0x3F7FFF));
        colors.put("green", new Color(0x00C853));
        colors.put("lime", new Color(0x7CFC00));
        colors.put("yellow", new Color(0xFFFF00));
        colors.put("orange", new Color(0xFF981F));
        colors.put("purple", new Color(0xA855F7));
        colors.put("magenta", new Color(0xFF00FF));
        colors.put("cyan", new Color(0x00FFFF));
        colors.put("pink", new Color(0xFF69B4));
        colors.put("white", new Color(0xFFFFFF));
        colors.put("gray", new Color(0xA0A0A0));
        colors.put("grey", new Color(0xA0A0A0));
        colors.put("black", new Color(0x000000));
        NAMED_COLORS = Collections.unmodifiableMap(colors);
    }

    private final FairyRingOrganizerConfig config;
    private String cachedRaw;
    private Map<String, Color> cachedColors = Collections.emptyMap();

    @Inject
    public FairyRingColorService(FairyRingOrganizerConfig config)
    {
        this.config = config;
    }

    public Color getFavoriteMenuColor(String code)
    {
        String normalized = FairyRingOrderService.normalizeCode(code);
        if (!FairyRingDestination.isValidCode(normalized))
        {
            return null;
        }

        String raw = config.favoriteMenuColors();
        raw = raw == null ? "" : raw;
        if (!raw.equals(cachedRaw))
        {
            cachedRaw = raw;
            cachedColors = parse(raw);
        }
        return cachedColors.get(normalized);
    }

    public void invalidate()
    {
        cachedRaw = null;
        cachedColors = Collections.emptyMap();
    }

    static Map<String, Color> parse(String raw)
    {
        if (raw == null || raw.trim().isEmpty())
        {
            return Collections.emptyMap();
        }

        Map<String, Color> result = new LinkedHashMap<>();
        for (String line : raw.split("\\R"))
        {
            String trimmed = line.trim();
            if (trimmed.isEmpty())
            {
                continue;
            }

            int comma = trimmed.indexOf(',');
            if (comma <= 0 || comma >= trimmed.length() - 1)
            {
                continue;
            }

            String code = FairyRingOrderService.normalizeCode(trimmed.substring(0, comma));
            if (!FairyRingDestination.isValidCode(code))
            {
                continue;
            }

            Color color = parseColor(trimmed.substring(comma + 1));
            if (color != null)
            {
                // Last valid line wins if a code appears more than once.
                result.put(code, color);
            }
        }
        return Collections.unmodifiableMap(result);
    }

    static Color parseColor(String value)
    {
        if (value == null)
        {
            return null;
        }

        String normalized = value.trim().toLowerCase(Locale.ROOT);
        Color named = NAMED_COLORS.get(normalized);
        if (named != null)
        {
            return named;
        }

        if (normalized.startsWith("#"))
        {
            normalized = normalized.substring(1);
        }
        else if (normalized.startsWith("0x"))
        {
            normalized = normalized.substring(2);
        }

        if (!normalized.matches("[0-9a-f]{6}"))
        {
            return null;
        }

        try
        {
            return new Color(Integer.parseInt(normalized, 16));
        }
        catch (NumberFormatException ignored)
        {
            return null;
        }
    }
}

package com.fairyringorganizer;

import java.util.Arrays;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

/**
 * Client-side destination catalogue used only for labels, matching, and sorting.
 * It is not an action table and does not invoke, select, or teleport to any fairy ring.
 *
 * The catalogue is intentionally not used as the validity gate. New Jagex codes that
 * match the three fairy-ring dials remain usable even before this enum is updated.
 */
public enum FairyRingDestination
{
    AIQ("Mudskipper Point"),
    AIR("South-east of Ardougne"),
    AIS("Auburn Valley"),
    AJP("Avium Savannah"),
    AJQ("Cave south of Dorgesh-Kaan"),
    AJR("Slayer cave"),
    AJS("Penguins near Miscellania"),
    AKP("Necropolis"),
    AKQ("Piscatoris Hunter area"),
    AKR("Hosidius Vinery"),
    AKS("Feldip Hunter area"),
    ALP("Lighthouse"),
    ALQ("Haunted Woods"),
    ALR("Abyssal Area"),
    ALS("McGrubor's Wood"),
    BIP("South-west of Mort Myre"),
    BIQ("Kalphite Hive"),
    BIS("Ardougne Zoo"),
    BJP("Isle of Souls"),
    BJR("Fisher King Realm"),
    BJS("Near Zul-Andra"),
    BKP("South of Castle Wars"),
    BKQ("Enchanted Valley"),
    BKR("Mort Myre Swamp"),
    BKS("Zanaris"),
    BLP("TzHaar area"),
    BLQ("Yu'biusk"),
    BLR("Legends' Guild"),
    BLS("Mount Quidamortem"),
    CIP("Miscellania"),
    CIQ("North-west of Yanille"),
    CIR("Farming Guild"),
    CIS("Arceuus Library"),
    CJQ("The Great Conch"),
    CJR("Sinclair Mansion"),
    CKP("Cosmic entity's plane"),
    CKQ("Aldarin"),
    CKR("Tai Bwo Wannai"),
    CKS("Canifis"),
    CLP("South of Draynor Village"),
    CLR("Ape Atoll"),
    CLS("Hazelmere's home"),
    DIP("Abyssal Nexus"),
    DIQ("Player-owned house"),
    DIR("Gorak's Plane"),
    DIS("Wizards' Tower"),
    DJP("Tower of Life"),
    DJR("Chasm of Fire"),
    DKP("South of Musa Point"),
    DKR("Edgeville", "Edgeville / GE", "Edgeville, Grand Exchange"),
    DKS("Polar Hunter area"),
    DLP("Grimstone Dungeon"),
    DLQ("North of Nardah"),
    DLR("Poison Waste"),
    DLS("The Hollows");

    // The three dials are A-D, I-L, and P-S respectively.
    private static final Pattern VALID_CODE = Pattern.compile("^[A-D][I-L][P-S]$");

    private static final Map<String, FairyRingDestination> BY_CODE = Arrays.stream(values())
        .collect(Collectors.toUnmodifiableMap(Enum::name, value -> value));

    private final String destination;
    private final String[] aliases;

    FairyRingDestination(String destination, String... aliases)
    {
        this.destination = destination;
        this.aliases = aliases == null ? new String[0] : aliases;
    }

    public String getCode()
    {
        return name();
    }

    public String getDestination()
    {
        return destination;
    }

    public static FairyRingDestination forCode(String code)
    {
        if (code == null)
        {
            return null;
        }
        return BY_CODE.get(normalize(code));
    }

    /**
     * Resolve a human-readable menu label back to its fairy-ring code. This is primarily
     * a compatibility path for other client-side menu-label plugins which can replace the
     * original bare code before Organizer's final menu presentation pass.
     */
    public static FairyRingDestination forDisplayAlias(String displayName)
    {
        String normalized = normalizeDisplayName(displayName);
        if (normalized.isEmpty())
        {
            return null;
        }

        for (FairyRingDestination destination : values())
        {
            if (normalizeDisplayName(destination.destination).equals(normalized))
            {
                return destination;
            }

            for (String alias : destination.aliases)
            {
                if (normalizeDisplayName(alias).equals(normalized))
                {
                    return destination;
                }
            }
        }
        return null;
    }

    private static String normalizeDisplayName(String value)
    {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    /**
     * Validates the shape of a fairy-ring code without requiring the code to already be
     * present in this local catalogue. This makes the plugin fail open when Jagex adds a
     * destination before the plugin catalogue is updated.
     */
    public static boolean isValidCode(String code)
    {
        return VALID_CODE.matcher(normalize(code)).matches();
    }

    public static String normalize(String code)
    {
        return code == null ? "" : code.replace(" ", "").trim().toUpperCase(Locale.ROOT);
    }
}

package com.fairyringorganizer;

import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;

/**
 * Implements local drag grips for manual ordering inside the Fairy Ring Travel Log.
 *
 * Mouse events that begin on the Organizer-drawn grip are consumed so they cannot fall through
 * to the underlying row. No synthetic MouseEvent is dispatched and no RuneScape widget op or
 * teleport action is invoked; a completed drag only persists a code order in ConfigManager.
 */
@Slf4j
@Singleton
public class FairyRingDragController
{
    static final int HANDLE_WIDTH = 12;
    static final int HANDLE_HEIGHT = 12;
    // The native favorite/add heart occupies the upper-left of each row. The manual
    // reorder grip lives directly underneath it, beside the destination text.
    static final int HANDLE_X = 2;
    static final int HANDLE_Y_OFFSET = 15;
    // A press on the grip is only an armed drag. The user must move vertically by this
    // many pixels before preview/reorder behavior begins, matching the feel of native
    // inventory dragging and preventing a simple click from changing the order.
    static final int DRAG_START_THRESHOLD = 6;

    private final Client client;
    private final MouseManager mouseManager;
    private final ClientThread clientThread;
    private final FairyRingOrganizerConfig config;
    private final FairyRingOrderService orderService;

    private final Map<FairyRingSection, List<FairyRingRow>> rowsBySection = new EnumMap<>(FairyRingSection.class);
    private final Map<FairyRingSection, Widget> containersBySection = new EnumMap<>(FairyRingSection.class);
    private final Map<FairyRingSection, LayoutSignature> layoutSignatures = new EnumMap<>(FairyRingSection.class);
    // Row spans belong to the destination row, not to a fixed slot. Keeping them beside the
    // live rows lets a Manual drop repack only the affected section without clearing every
    // forced position and briefly exposing Jagex's intermediate icon state.
    private final Map<FairyRingSection, Map<String, Integer>> rowSpansBySection = new EnumMap<>(FairyRingSection.class);

    // Mouse callbacks do not run on the RuneLite client thread. Cache bounds on the
    // client thread so the AWT listener never inspects live Widget state.
    private final Map<String, HandleTarget> activeHandleTargets = new ConcurrentHashMap<>();
    // Screen-space row geometry is cached separately from handle visibility so the drag preview
    // can show an insertion point even when a row itself is partially outside the scroll viewport.
    private final Map<String, RowTarget> activeRowTargets = new ConcurrentHashMap<>();
    private final Map<FairyRingSection, List<String>> orderedCodesBySection = new ConcurrentHashMap<>();
    private final Map<FairyRingSection, Rectangle> viewportBoundsBySection = new ConcurrentHashMap<>();
    private volatile DragState dragState;

    private final MouseAdapter mouseListener = new MouseAdapter()
    {
        @Override
        public MouseEvent mousePressed(MouseEvent event)
        {
            if (!SwingUtilities.isLeftMouseButton(event))
            {
                return event;
            }

            DragState state = findHandle(event.getX(), event.getY());
            if (state == null)
            {
                return event;
            }

            dragState = state;
            event.consume();
            return event;
        }

        @Override
        public MouseEvent mouseDragged(MouseEvent event)
        {
            DragState state = dragState;
            if (state == null)
            {
                return event;
            }

            state.lastMouseY = event.getY();
            if (!state.active
                && Math.abs(state.lastMouseY - state.pressMouseY) >= DRAG_START_THRESHOLD)
            {
                state.active = true;
            }

            // The grip is Organizer-owned local UI. Consume every movement that began on it
            // so the underlying Fairy Ring row never receives a partial click/drag.
            event.consume();
            return event;
        }

        @Override
        public MouseEvent mouseReleased(MouseEvent event)
        {
            DragState completed = dragState;
            if (completed == null)
            {
                return event;
            }

            completed.lastMouseY = event.getY();
            dragState = null;
            event.consume();

            // A click (or tiny hand jitter) is deliberately a no-op. Only a drag that
            // crossed the activation threshold is allowed to save a new order.
            if (completed.active)
            {
                clientThread.invokeLater(() -> completeDrag(completed));
            }
            return event;
        }
    };

    @Inject
    public FairyRingDragController(
        Client client,
        MouseManager mouseManager,
        ClientThread clientThread,
        FairyRingOrganizerConfig config,
        FairyRingOrderService orderService)
    {
        this.client = client;
        this.mouseManager = mouseManager;
        this.clientThread = clientThread;
        this.config = config;
        this.orderService = orderService;
        rowsBySection.put(FairyRingSection.FAVORITES, new ArrayList<>());
        rowsBySection.put(FairyRingSection.REMAINING, new ArrayList<>());
    }

    public void start()
    {
        // This listener only observes/consumes the user's real mouse events when they begin on
        // Organizer's overlay grip. It never dispatches or synthesizes mouse input.
        mouseManager.registerMouseListener(mouseListener);
    }

    public void stop()
    {
        mouseManager.unregisterMouseListener(mouseListener);

        // Plugin shutdown may be initiated outside the RuneLite client thread. Do not
        // touch live widgets here; FairyRingInterfaceController.restoreNative() performs
        // the visual cleanup on the client thread. Clearing these thread-safe/local
        // mouse targets immediately prevents any further drag from being recognized.
        dragState = null;
        activeHandleTargets.clear();
        activeRowTargets.clear();
        orderedCodesBySection.clear();
        viewportBoundsBySection.clear();
        rowSpansBySection.clear();
    }

    /** Must be called on the RuneLite client thread. */
    public void updateRows(FairyRingSection section, List<FairyRingRow> rows, SortMode mode, boolean draggingAllowed)
    {
        updateRows(section, rows, mode, draggingAllowed, null);
    }

    /** Must be called on the RuneLite client thread. */
    public void updateRows(
        FairyRingSection section,
        List<FairyRingRow> rows,
        SortMode mode,
        boolean draggingAllowed,
        Map<String, Integer> rowSpans)
    {
        rowsBySection.put(section, new ArrayList<>(rows));
        if (rows.isEmpty())
        {
            rowSpansBySection.remove(section);
        }
        else if (rowSpans != null && !rowSpans.isEmpty())
        {
            rowSpansBySection.put(section, new java.util.HashMap<>(rowSpans));
        }
        else if (!rowSpansBySection.containsKey(section))
        {
            rowSpansBySection.put(section, deriveDisplayedRowSpans(rows));
        }
        List<String> orderedCodes = new ArrayList<>();
        for (FairyRingRow row : rows)
        {
            orderedCodes.add(row.getCode());
        }
        orderedCodesBySection.put(section, java.util.Collections.unmodifiableList(orderedCodes));

        if (rows.isEmpty())
        {
            containersBySection.remove(section);
            layoutSignatures.remove(section);
        }
        else
        {
            containersBySection.put(section, rows.get(0).getContainer());
        }
        boolean manual = draggingAllowed && mode == SortMode.MANUAL && config.showDragHandles();
        String sectionPrefix = section.name() + ':';
        Set<String> liveKeys = new HashSet<>();

        // Deactivate this section first; current rows will be added back below.
        activeHandleTargets.keySet().removeIf(key -> key.startsWith(sectionPrefix));
        activeRowTargets.keySet().removeIf(key -> key.startsWith(sectionPrefix));
        viewportBoundsBySection.remove(section);
        if (!manual && dragState != null && dragState.section == section)
        {
            dragState = null;
        }

        for (FairyRingRow row : rows)
        {
            String key = handleKey(row);
            liveKeys.add(key);

            if (!manual)
            {
                continue;
            }

            // Keep the drag target local to RuneLite instead of injecting a custom Widget child.
            // Jagex rebuilds the fairy-ring dynamic child list and deletes injected children;
            // FairyRingDragOverlay renders the persistent visual grip and drag preview from the
            // cached screen-space geometry produced here.
            cacheRowAndHandleBounds(key, section, row);
        }

        // Remove stale targets left by an older membership/interface build.
        activeHandleTargets.keySet().removeIf(key -> key.startsWith(sectionPrefix) && !liveKeys.contains(key));
        activeRowTargets.keySet().removeIf(key -> key.startsWith(sectionPrefix) && !liveKeys.contains(key));

        Widget container = containersBySection.get(section);
        if (container != null && manual)
        {
            layoutSignatures.put(section, LayoutSignature.capture(container, visibleViewportBounds(container)));
        }
        else
        {
            layoutSignatures.remove(section);
        }
    }

    /**
     * ClientTick-safe fast path. Only the two section containers are sampled every frame.
     * Individual handle bounds are refreshed only after scrolling, resizing, or moving the
     * list container, avoiding dozens of widget reads/allocations every 20 ms.
     */
    public void refreshHandleBoundsIfLayoutChanged()
    {
        for (FairyRingSection section : FairyRingSection.values())
        {
            Widget container = containersBySection.get(section);
            LayoutSignature previous = layoutSignatures.get(section);
            if (container == null || previous == null || previous.matches(container, visibleViewportBounds(container)))
            {
                continue;
            }

            refreshSectionHandleBounds(section);
            layoutSignatures.put(section, LayoutSignature.capture(container, visibleViewportBounds(container)));
        }
    }

    private void refreshSectionHandleBounds(FairyRingSection section)
    {
        String prefix = section.name() + ':';
        activeHandleTargets.keySet().removeIf(key -> key.startsWith(prefix));
        activeRowTargets.keySet().removeIf(key -> key.startsWith(prefix));
        viewportBoundsBySection.remove(section);

        List<FairyRingRow> rows = rowsBySection.get(section);
        if (rows == null)
        {
            return;
        }

        for (FairyRingRow row : rows)
        {
            cacheRowAndHandleBounds(handleKey(row), section, row);
        }
    }

    public void cancelActiveDrag()
    {
        dragState = null;
    }

    public void clear()
    {
        dragState = null;
        activeHandleTargets.clear();
        activeRowTargets.clear();
        orderedCodesBySection.clear();
        viewportBoundsBySection.clear();
        containersBySection.clear();
        layoutSignatures.clear();
        rowSpansBySection.clear();
        rowsBySection.get(FairyRingSection.FAVORITES).clear();
        rowsBySection.get(FairyRingSection.REMAINING).clear();
    }

    private void cacheRowAndHandleBounds(String key, FairyRingSection section, FairyRingRow row)
    {
        Widget container = row.getContainer();
        Rectangle containerBounds = container == null ? null : container.getBounds();
        if (container == null || containerBounds == null || containerBounds.isEmpty())
        {
            activeHandleTargets.remove(key);
            activeRowTargets.remove(key);
            return;
        }

        Rectangle viewportBounds = visibleViewportBounds(container);
        if (viewportBounds == null || viewportBounds.isEmpty())
        {
            activeHandleTargets.remove(key);
            activeRowTargets.remove(key);
            return;
        }
        viewportBoundsBySection.put(section, new Rectangle(viewportBounds));

        int rowTop = containerBounds.y + row.getBaseY() - container.getScrollY();
        int rowHeight = Math.max(1, row.getLogicalHeight());

        // Keep the preview lane inside the list content and stop before the native scrollbar.
        int laneLeft = Math.max(containerBounds.x, viewportBounds.x);
        int laneRight = Math.min(containerBounds.x + containerBounds.width,
            viewportBounds.x + viewportBounds.width);
        Widget scrollbar = client.getWidget(InterfaceID.FairyringsLog.SCROLLBAR);
        Rectangle scrollbarBounds = scrollbar == null || scrollbar.isHidden() ? null : scrollbar.getBounds();
        if (scrollbarBounds != null && !scrollbarBounds.isEmpty() && scrollbarBounds.x > laneLeft)
        {
            laneRight = Math.min(laneRight, scrollbarBounds.x);
        }
        int laneWidth = Math.max(1, laneRight - laneLeft);

        Rectangle fullRowBounds = new Rectangle(laneLeft, rowTop, laneWidth, rowHeight);
        Rectangle visibleRowBounds = fullRowBounds.intersection(viewportBounds);
        activeRowTargets.put(key, new RowTarget(section, row.getCode(), fullRowBounds, visibleRowBounds));

        // Overlay graphics do not inherit Jagex's scroll-widget clipping. Calculate the grip at
        // the row's current scrolled screen position, then only expose it when the complete
        // 12x12 target is inside the actual visible Fairy Ring list viewport. This keeps both
        // the painted grip and its mouse target from floating above/below the Travel Log when
        // a row scrolls out of view.
        int x = containerBounds.x + HANDLE_X;
        int y = rowTop + HANDLE_Y_OFFSET;
        Rectangle desiredBounds = new Rectangle(x, y, HANDLE_WIDTH, HANDLE_HEIGHT);

        if (!viewportBounds.contains(desiredBounds))
        {
            activeHandleTargets.remove(key);
            return;
        }

        activeHandleTargets.put(key, new HandleTarget(section, row.getCode(), desiredBounds));
    }

    /**
     * Returns the screen-space rectangle in which this section is actually visible. The Fairy
     * Ring favorites/remaining widgets are scroll contents, so their own bounds can move outside
     * the Travel Log while scrolling. Intersecting their ancestor bounds supplies normal Jagex
     * clipping, and the shared Fairy Ring scrollbar supplies an additional stable vertical clip.
     */
    private Rectangle visibleViewportBounds(Widget container)
    {
        Rectangle clip = null;
        for (Widget parent = container.getParent(); parent != null; parent = parent.getParent())
        {
            Rectangle bounds = parent.getBounds();
            if (bounds == null || bounds.isEmpty())
            {
                continue;
            }

            clip = clip == null ? new Rectangle(bounds) : clip.intersection(bounds);
            if (clip.isEmpty())
            {
                return clip;
            }
        }

        // The Favorites and Remaining sections share the same visible scroll window. Use the
        // scrollbar's fixed screen-space vertical range so an overlay grip can never render in
        // the title/header or outside the Travel Log merely because the content widget itself
        // has scrolled there.
        Widget scrollbar = client.getWidget(InterfaceID.FairyringsLog.SCROLLBAR);
        Rectangle scrollbarBounds = scrollbar == null || scrollbar.isHidden() ? null : scrollbar.getBounds();
        if (scrollbarBounds != null && !scrollbarBounds.isEmpty())
        {
            Rectangle verticalClip = new Rectangle(
                0, scrollbarBounds.y, Math.max(1, client.getCanvasWidth()), scrollbarBounds.height);
            clip = clip == null ? verticalClip : clip.intersection(verticalClip);
        }

        // Fallback for an unexpected future hierarchy: keep the handle constrained to the
        // section widget rather than allowing an unbounded overlay target.
        return clip == null ? new Rectangle(container.getBounds()) : clip;
    }

    List<Rectangle> getVisibleHandleBounds()
    {
        List<Rectangle> bounds = new ArrayList<>();
        for (HandleTarget target : activeHandleTargets.values())
        {
            if (target != null && target.bounds != null && !target.bounds.isEmpty())
            {
                bounds.add(new Rectangle(target.bounds));
            }
        }
        return bounds;
    }

    /**
     * Returns an immutable screen-space preview for the current drag. The overlay uses this to
     * highlight the row being moved and draw a lighter-brown insertion marker at the exact slot
     * that completeDrag() will save if the mouse is released now.
     */
    DragVisual getDragVisual()
    {
        DragState state = dragState;
        if (state == null || !state.active)
        {
            return null;
        }

        DropPlan plan = calculateDropPlan(state);
        if (plan == null)
        {
            return null;
        }

        RowTarget source = activeRowTargets.get(state.section.name() + ':' + state.code);
        Rectangle viewport = viewportBoundsBySection.get(state.section);

        /*
         * Once a drag has activated, the held-row preview belongs to the mouse, not to the
         * scrolling list. Keep the press-time row rectangle as the visual anchor and translate
         * it only by the mouse's vertical displacement. If the user wheel-scrolls while holding
         * the mouse still, the list moves underneath this rectangle while the rectangle stays
         * under the cursor. This matches native inventory-style dragging much more closely.
         */
        Rectangle sourceHighlight = null;
        Rectangle pressBounds = state.pressSourceBounds;
        if (pressBounds != null && !pressBounds.isEmpty())
        {
            int mouseDeltaY = state.lastMouseY - state.pressMouseY;
            int laneX = source == null || source.fullBounds == null
                ? pressBounds.x : source.fullBounds.x;
            int laneWidth = source == null || source.fullBounds == null
                ? pressBounds.width : source.fullBounds.width;
            sourceHighlight = new Rectangle(
                laneX,
                pressBounds.y + mouseDeltaY,
                laneWidth,
                pressBounds.height);

            if (viewport != null && !viewport.isEmpty())
            {
                sourceHighlight = sourceHighlight.intersection(viewport);
                if (sourceHighlight.isEmpty())
                {
                    sourceHighlight = null;
                }
            }
        }

        if (viewport == null || viewport.isEmpty())
        {
            return sourceHighlight == null ? null : new DragVisual(sourceHighlight, null);
        }

        Rectangle lane = plan.referenceLane;
        if (lane == null || lane.isEmpty())
        {
            return new DragVisual(sourceHighlight, null);
        }

        Rectangle insertion = new Rectangle(lane.x, plan.insertionY - 2, lane.width, 5)
            .intersection(viewport);
        if (insertion.isEmpty())
        {
            insertion = null;
        }
        return new DragVisual(sourceHighlight, insertion);
    }

    private DragState findHandle(int x, int y)
    {
        for (HandleTarget target : activeHandleTargets.values())
        {
            if (target.bounds.contains(x, y))
            {
                RowTarget source = activeRowTargets.get(target.section.name() + ':' + target.code);
                Rectangle sourceBounds = source == null || source.fullBounds == null
                    ? null : new Rectangle(source.fullBounds);
                return new DragState(target.section, target.code, y, sourceBounds);
            }
        }
        return null;
    }

    /** Runs on the RuneLite client thread. */
    private void completeDrag(DragState state)
    {
        DropPlan plan = calculateDropPlan(state);
        if (plan == null)
        {
            return;
        }

        int sourceIndex = plan.currentOrder.indexOf(state.code);
        if (sourceIndex < 0 || sourceIndex == plan.targetIndex)
        {
            // The user activated a drag but never crossed a neighboring row's snap point.
            // Do not rewrite configuration for a no-op drop.
            return;
        }

        List<String> movedOrder = orderService.move(
            state.section, plan.currentOrder, state.code, plan.targetIndex);
        if (movedOrder.isEmpty())
        {
            return;
        }

        // Do not schedule a full Configure refresh for a local Manual reorder. A full refresh
        // begins by clearing forced positions in BOTH sections, which can expose Jagex's
        // intermediate image-widget state for a frame (Remaining icons vanish
        // and a green add-favourite heart can flash). We already have every live row and its
        // native span, so repack only the section that changed and refresh its local hitboxes.
        applyManualOrderLocally(state.section, movedOrder);
    }

    private void applyManualOrderLocally(FairyRingSection section, List<String> orderedCodes)
    {
        applyOrderLocally(section, orderedCodes, SortMode.MANUAL, true);
        if (config.debugDiagnostics())
        {
            log.debug("Fairy Ring Organizer: manual order saved: section={} codes={}",
                section, String.join(",", orderedCodes));
        }
    }

    /**
     * Applies a sort-mode transition using the already-settled live rows for only the affected
     * section. This intentionally avoids InterfaceController.refreshNow(), whose first step clears
     * forced positions in BOTH sections and can briefly expose Jagex's native green heart/icon
     * state before the Organizer permutation is restored.
     *
     * @return true when a live section was available and the transition was applied locally.
     */
    public boolean applySortModeLocally(FairyRingSection section, SortMode mode, boolean draggingAllowed)
    {
        List<FairyRingRow> currentRows = rowsBySection.get(section);
        if (currentRows == null || currentRows.isEmpty())
        {
            return false;
        }

        List<String> visibleCodes = new ArrayList<>();
        for (FairyRingRow row : currentRows)
        {
            visibleCodes.add(row.getCode());
        }

        List<String> orderedCodes = orderService.sortCodes(visibleCodes, section, mode);
        if (orderedCodes.isEmpty())
        {
            return false;
        }

        applyOrderLocally(section, orderedCodes, mode, draggingAllowed);
        if (config.debugDiagnostics())
        {
            log.debug("Fairy Ring Organizer: sort changed: section={} mode={}", section, mode);
        }
        return true;
    }

    private void applyOrderLocally(
        FairyRingSection section, List<String> orderedCodes, SortMode mode, boolean draggingAllowed)
    {
        List<FairyRingRow> currentRows = rowsBySection.get(section);
        if (currentRows == null || currentRows.isEmpty())
        {
            return;
        }

        Map<String, FairyRingRow> byCode = new java.util.HashMap<>();
        int nextY = Integer.MAX_VALUE;
        for (FairyRingRow row : currentRows)
        {
            byCode.put(row.getCode(), row);
            nextY = Math.min(nextY, row.getBaseY());
        }
        if (nextY == Integer.MAX_VALUE)
        {
            return;
        }

        Map<String, Integer> spans = rowSpansBySection.get(section);
        if (spans == null || spans.isEmpty())
        {
            spans = deriveDisplayedRowSpans(currentRows);
            rowSpansBySection.put(section, spans);
        }

        List<FairyRingRow> reorderedRows = new ArrayList<>();
        for (String code : orderedCodes)
        {
            FairyRingRow row = byCode.remove(code);
            if (row == null)
            {
                continue;
            }

            row.moveTo(nextY);
            reorderedRows.add(row);
            nextY += Math.max(1, spans.getOrDefault(code, Math.max(32, row.getLogicalHeight())));
        }

        // Normal sort transitions operate against the same complete live section. If a future
        // client change leaves an unmatched row, append it rather than dropping it from local
        // state or forcing a full cross-section refresh solely for that defensive edge case.
        for (FairyRingRow row : currentRows)
        {
            if (!byCode.containsKey(row.getCode()))
            {
                continue;
            }
            row.moveTo(nextY);
            reorderedRows.add(row);
            nextY += Math.max(1, spans.getOrDefault(row.getCode(), Math.max(32, row.getLogicalHeight())));
            byCode.remove(row.getCode());
        }

        updateRows(section, reorderedRows, mode, draggingAllowed, spans);
    }

    /**
     * Derives the destination-owned vertical footprint from the currently displayed layout.
     * InterfaceController normally supplies the authoritative native spans. This fallback is
     * retained for safety if updateRows is ever called by a future path without that map.
     */
    private static Map<String, Integer> deriveDisplayedRowSpans(List<FairyRingRow> rows)
    {
        Map<String, Integer> result = new java.util.HashMap<>();
        if (rows == null || rows.isEmpty())
        {
            return result;
        }

        List<FairyRingRow> ordered = new ArrayList<>(rows);
        ordered.sort(java.util.Comparator.comparingInt(FairyRingRow::getBaseY));
        List<Integer> trailingPads = new ArrayList<>();
        for (int i = 0; i + 1 < ordered.size(); i++)
        {
            FairyRingRow row = ordered.get(i);
            int span = Math.max(1, ordered.get(i + 1).getBaseY() - row.getBaseY());
            result.put(row.getCode(), span);
            trailingPads.add(Math.max(0, span - row.getLogicalHeight()));
        }

        FairyRingRow last = ordered.get(ordered.size() - 1);
        int pad = 3;
        if (!trailingPads.isEmpty())
        {
            trailingPads.sort(Integer::compareTo);
            pad = trailingPads.get(trailingPads.size() / 2);
        }
        result.put(last.getCode(), Math.max(1, last.getLogicalHeight() + pad));
        return result;
    }

    /**
     * Calculates both the saved target index and the matching visual insertion position from the
     * same cached geometry. Keeping these together guarantees the brown preview cannot advertise
     * a different destination than the order that will actually be written on mouse release.
     */
    private DropPlan calculateDropPlan(DragState state)
    {
        List<String> current = orderedCodesBySection.get(state.section);
        if (current == null || current.isEmpty() || !current.contains(state.code))
        {
            return null;
        }

        String sourceKey = state.section.name() + ':' + state.code;
        RowTarget source = activeRowTargets.get(sourceKey);
        if (source == null || source.fullBounds == null || source.fullBounds.isEmpty())
        {
            return null;
        }

        /*
         * Treat the dragged row's CENTER as following the mouse displacement from the
         * PRESS-TIME row position. Do not re-anchor this center to source.fullBounds after a
         * scroll: source.fullBounds intentionally moves with the list, while the held row should
         * stay under a stationary cursor. Neighboring RowTargets are still refreshed on scroll,
         * so they move underneath this fixed dragged center and the insertion slot updates.
         */
        int mouseDeltaY = state.lastMouseY - state.pressMouseY;
        Rectangle dragAnchor = state.pressSourceBounds == null
            ? source.fullBounds : state.pressSourceBounds;
        double draggedCenterY = dragAnchor.getCenterY() + mouseDeltaY;

        List<String> remaining = new ArrayList<>(current);
        remaining.remove(state.code);

        // Each neighboring row center is a snap threshold. Until the dragged row's center
        // crosses one of those centers, the placement marker remains on its current slot.
        int target = remaining.size();
        for (int index = 0; index < remaining.size(); index++)
        {
            RowTarget rowTarget = activeRowTargets.get(state.section.name() + ':' + remaining.get(index));
            Rectangle bounds = rowTarget == null ? null : rowTarget.fullBounds;
            if (bounds != null && draggedCenterY < bounds.getCenterY())
            {
                target = index;
                break;
            }
        }

        int boundedTarget = Math.max(0, Math.min(target, remaining.size()));

        /*
         * Make the placement marker direction-aware, matching the visual language of
         * dragging through a native list:
         *
         * - moving UP:    draw on the TOP edge of the row the dragged entry would precede;
         * - moving DOWN:  draw on the BOTTOM edge of the row the dragged entry would follow.
         *
         * boundedTarget is still the one authoritative saved insertion index. This block
         * only chooses which physical edge represents that same insertion boundary.
         */
        int sourceIndex = current.indexOf(state.code);
        boolean movingUp = boundedTarget < sourceIndex
            || (boundedTarget == sourceIndex && mouseDeltaY < 0);
        boolean movingDown = boundedTarget > sourceIndex
            || (boundedTarget == sourceIndex && mouseDeltaY > 0);

        Rectangle referenceLane = source.fullBounds;
        int insertionY = movingUp
            ? source.fullBounds.y
            : source.fullBounds.y + source.fullBounds.height;

        if (movingUp && boundedTarget >= 0 && boundedTarget < current.size())
        {
            // Inserting at index N while moving upward means the dragged row will appear
            // immediately BEFORE the row currently occupying index N.
            String slotCode = current.get(boundedTarget);
            RowTarget slot = activeRowTargets.get(state.section.name() + ':' + slotCode);
            if (slot != null && slot.fullBounds != null && !slot.fullBounds.isEmpty())
            {
                referenceLane = slot.fullBounds;
                insertionY = slot.fullBounds.y;
            }
        }
        else if (movingDown && boundedTarget >= 0 && boundedTarget < current.size())
        {
            // Inserting at index N while moving downward means the dragged row will appear
            // immediately AFTER the row currently occupying index N.
            String slotCode = current.get(boundedTarget);
            RowTarget slot = activeRowTargets.get(state.section.name() + ':' + slotCode);
            if (slot != null && slot.fullBounds != null && !slot.fullBounds.isEmpty())
            {
                referenceLane = slot.fullBounds;
                insertionY = slot.fullBounds.y + slot.fullBounds.height;
            }
        }

        return new DropPlan(new ArrayList<>(current), boundedTarget, insertionY,
            referenceLane == null ? null : new Rectangle(referenceLane));
    }

    private static String handleKey(FairyRingRow row)
    {
        return row.getSection().name() + ':' + row.getCode();
    }

    private static final class LayoutSignature
    {
        private final int scrollY;
        private final Rectangle bounds;
        private final Rectangle viewportBounds;

        private LayoutSignature(int scrollY, Rectangle bounds, Rectangle viewportBounds)
        {
            this.scrollY = scrollY;
            this.bounds = bounds;
            this.viewportBounds = viewportBounds;
        }

        private static LayoutSignature capture(Widget container, Rectangle viewport)
        {
            Rectangle bounds = container.getBounds();
            return new LayoutSignature(
                container.getScrollY(),
                bounds == null ? null : new Rectangle(bounds),
                viewport == null ? null : new Rectangle(viewport));
        }

        private boolean matches(Widget container, Rectangle currentViewport)
        {
            if (container.getScrollY() != scrollY)
            {
                return false;
            }
            Rectangle currentBounds = container.getBounds();
            if (!(bounds == null ? currentBounds == null : bounds.equals(currentBounds)))
            {
                return false;
            }
            return viewportBounds == null ? currentViewport == null : viewportBounds.equals(currentViewport);
        }

        @Override
        public boolean equals(Object other)
        {
            if (this == other)
            {
                return true;
            }
            if (!(other instanceof LayoutSignature))
            {
                return false;
            }
            LayoutSignature that = (LayoutSignature) other;
            if (scrollY != that.scrollY)
            {
                return false;
            }
            if (!(bounds == null ? that.bounds == null : bounds.equals(that.bounds)))
            {
                return false;
            }
            return viewportBounds == null ? that.viewportBounds == null : viewportBounds.equals(that.viewportBounds);
        }

        @Override
        public int hashCode()
        {
            int result = 31 * scrollY + (bounds == null ? 0 : bounds.hashCode());
            return 31 * result + (viewportBounds == null ? 0 : viewportBounds.hashCode());
        }
    }

    private static final class RowTarget
    {
        private final FairyRingSection section;
        private final String code;
        private final Rectangle fullBounds;
        private final Rectangle visibleBounds;

        private RowTarget(FairyRingSection section, String code, Rectangle fullBounds, Rectangle visibleBounds)
        {
            this.section = section;
            this.code = code;
            this.fullBounds = new Rectangle(fullBounds);
            this.visibleBounds = visibleBounds == null ? null : new Rectangle(visibleBounds);
        }
    }

    private static final class DropPlan
    {
        private final List<String> currentOrder;
        private final int targetIndex;
        private final int insertionY;
        private final Rectangle referenceLane;

        private DropPlan(List<String> currentOrder, int targetIndex, int insertionY, Rectangle referenceLane)
        {
            this.currentOrder = currentOrder;
            this.targetIndex = targetIndex;
            this.insertionY = insertionY;
            this.referenceLane = referenceLane;
        }
    }

    static final class DragVisual
    {
        private final Rectangle sourceHighlight;
        private final Rectangle insertionMarker;

        private DragVisual(Rectangle sourceHighlight, Rectangle insertionMarker)
        {
            this.sourceHighlight = sourceHighlight == null ? null : new Rectangle(sourceHighlight);
            this.insertionMarker = insertionMarker == null ? null : new Rectangle(insertionMarker);
        }

        Rectangle getSourceHighlight()
        {
            return sourceHighlight == null ? null : new Rectangle(sourceHighlight);
        }

        Rectangle getInsertionMarker()
        {
            return insertionMarker == null ? null : new Rectangle(insertionMarker);
        }
    }

    private static final class HandleTarget
    {
        private final FairyRingSection section;
        private final String code;
        private final Rectangle bounds;

        private HandleTarget(FairyRingSection section, String code, Rectangle bounds)
        {
            this.section = section;
            this.code = code;
            this.bounds = bounds;
        }
    }

    private static final class DragState
    {
        private final FairyRingSection section;
        private final String code;
        private final int pressMouseY;
        private final Rectangle pressSourceBounds;
        private volatile int lastMouseY;
        private volatile boolean active;

        private DragState(FairyRingSection section, String code, int mouseY, Rectangle sourceBounds)
        {
            this.section = section;
            this.code = code;
            this.pressMouseY = mouseY;
            this.pressSourceBounds = sourceBounds == null ? null : new Rectangle(sourceBounds);
            this.lastMouseY = mouseY;
        }
    }
}

package com.fairyringorganizer;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the manual-sort grip without adding custom children to Jagex's fairy-ring widgets.
 * Jagex rebuilds the Configure child list during interface scripts, so injected Widget children
 * are not durable. An overlay is purely client-side presentation and follows the stable hitboxes
 * calculated by FairyRingDragController.
 */
@Singleton
public class FairyRingDragOverlay extends Overlay
{
    private static final Color GRIP_COLOR = new Color(0xFF981F);
    private static final Color GRIP_SHADOW = new Color(0, 0, 0, 180);
    // Inventory-like drag feedback: a soft lighter-brown wash marks the row being moved,
    // while a brighter brown bar shows the exact slot that will receive it on release.
    private static final Color DRAGGED_ROW_FILL = new Color(188, 145, 88, 72);
    private static final Color DRAGGED_ROW_BORDER = new Color(232, 194, 139, 180);
    private static final Color DROP_MARKER_FILL = new Color(214, 171, 107, 220);
    private static final Color DROP_MARKER_BORDER = new Color(255, 221, 166, 230);

    private final FairyRingDragController dragController;

    @Inject
    public FairyRingDragOverlay(FairyRingDragController dragController)
    {
        this.dragController = dragController;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(PRIORITY_HIGH);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        FairyRingDragController.DragVisual dragVisual = dragController.getDragVisual();
        if (dragVisual != null)
        {
            drawDragPreview(graphics, dragVisual);
        }

        List<Rectangle> handles = dragController.getVisibleHandleBounds();
        for (Rectangle bounds : handles)
        {
            drawGrip(graphics, bounds);
        }
        return null;
    }

    private static void drawDragPreview(Graphics2D graphics, FairyRingDragController.DragVisual dragVisual)
    {
        Rectangle source = dragVisual.getSourceHighlight();
        if (source != null && !source.isEmpty())
        {
            graphics.setColor(DRAGGED_ROW_FILL);
            graphics.fillRoundRect(source.x, source.y, source.width, source.height, 4, 4);
            graphics.setColor(DRAGGED_ROW_BORDER);
            graphics.drawRoundRect(source.x, source.y,
                Math.max(0, source.width - 1), Math.max(0, source.height - 1), 4, 4);
        }

        Rectangle marker = dragVisual.getInsertionMarker();
        if (marker != null && !marker.isEmpty())
        {
            graphics.setColor(DROP_MARKER_FILL);
            graphics.fillRoundRect(marker.x, marker.y, marker.width, marker.height, 4, 4);
            graphics.setColor(DROP_MARKER_BORDER);
            graphics.drawRoundRect(marker.x, marker.y,
                Math.max(0, marker.width - 1), Math.max(0, marker.height - 1), 4, 4);
        }
    }

    private static void drawGrip(Graphics2D graphics, Rectangle bounds)
    {
        // Three short horizontal bars: visually equivalent to a compact "drag" handle and
        // independent of RuneScape font glyph support. Keep it within the same mouse target.
        int left = bounds.x + 2;
        int right = bounds.x + Math.max(7, bounds.width - 2);
        int centerY = bounds.y + bounds.height / 2;

        graphics.setColor(GRIP_SHADOW);
        graphics.drawLine(left + 1, centerY - 3 + 1, right + 1, centerY - 3 + 1);
        graphics.drawLine(left + 1, centerY + 1, right + 1, centerY + 1);
        graphics.drawLine(left + 1, centerY + 3 + 1, right + 1, centerY + 3 + 1);

        graphics.setColor(GRIP_COLOR);
        graphics.drawLine(left, centerY - 3, right, centerY - 3);
        graphics.drawLine(left, centerY, right, centerY);
        graphics.drawLine(left, centerY + 3, right, centerY + 3);
    }
}

package com.fairyringorganizer;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;

/**
 * Observes the actual Jagex Favorites membership without changing it or invoking heart actions.
 * A membership change must be seen twice before it is committed locally, which avoids treating
 * an asynchronously-building interface as a series of favorite/unfavorite transitions.
 */
public class FairyRingFavoriteStateService
{
    private static final int REQUIRED_IDENTICAL_OBSERVATIONS = 2;

    private final FairyRingOrderService orderService;
    private Set<String> committed;
    private Set<String> candidate;
    private int candidateObservations;

    @Inject
    public FairyRingFavoriteStateService(FairyRingOrderService orderService)
    {
        this.orderService = orderService;
    }

    public boolean observe(List<String> favoriteCodes)
    {
        Set<String> current = normalize(favoriteCodes);

        if (committed != null && committed.equals(current))
        {
            candidate = null;
            candidateObservations = 0;
            return false;
        }

        if (candidate != null && candidate.equals(current))
        {
            candidateObservations++;
        }
        else
        {
            candidate = current;
            candidateObservations = 1;
        }

        if (candidateObservations < REQUIRED_IDENTICAL_OBSERVATIONS)
        {
            return false;
        }

        boolean changedOrder = false;
        if (committed == null)
        {
            // First stable view is only a baseline; existing favorites are not "new".
            committed = new LinkedHashSet<>(candidate);
        }
        else
        {
            List<String> newlyFavorited = new ArrayList<>();
            for (String code : candidate)
            {
                if (!committed.contains(code))
                {
                    newlyFavorited.add(code);
                }
            }

            if (!newlyFavorited.isEmpty())
            {
                orderService.appendFavoritesToBottom(new ArrayList<>(candidate), newlyFavorited);
                changedOrder = true;
            }
            committed = new LinkedHashSet<>(candidate);
        }

        candidate = null;
        candidateObservations = 0;
        return changedOrder;
    }

    public void reset()
    {
        committed = null;
        candidate = null;
        candidateObservations = 0;
    }

    private static Set<String> normalize(List<String> codes)
    {
        Set<String> result = new LinkedHashSet<>();
        if (codes == null)
        {
            return result;
        }

        for (String code : codes)
        {
            String normalized = FairyRingOrderService.normalizeCode(code);
            if (FairyRingDestination.isValidCode(normalized))
            {
                result.add(normalized);
            }
        }
        return result;
    }
}

package com.fairyringorganizer;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.FontTypeFace;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;

/**
 * Applies ordering and labels to Jagex's existing Fairy Ring Travel Log list widgets.
 *
 * Scope is limited to the Favorites/Remaining rows, their divider, and scroll presentation.
 * The fairy-ring dials, confirm/teleport control, game-world click zones, and unrelated game
 * interfaces are never moved or resized. During Search, Jagex remains the sole owner of row
 * visibility and filtered-list geometry.
 */
public class FairyRingInterfaceController
{
    private final Client client;
    private final ClientThread clientThread;
    private final FairyRingOrganizerConfig config;
    private final FairyRingWidgetScanner scanner;
    private final FairyRingOrderService orderService;
    private final FairyRingLabelService labelService;
    private final FairyRingDragController dragController;
    private final FairyRingSearchController searchController;
    private final FairyRingNativeStateService nativeStateService;
    private final FairyRingFavoriteStateService favoriteStateService;

    private boolean refreshPending;
    private boolean interfaceActive;
    private boolean initialRenderRefreshPending;
    private boolean fairyBuildCallbackSeen;
    private boolean refreshOnNextGameTick;
    private boolean deferCurrentBuildToGameTick;
    private boolean waitForNativeGeometry;
    private Widget dividerOverrideWidget;
    // Search owns row visibility/compaction. While non-empty search text is present,
    // Organizer deliberately yields row positioning to the native interface and only
    // resumes saved ordering once the search is cleared.
    private boolean searchPresentationActive;

    @Inject
    public FairyRingInterfaceController(
        Client client,
        ClientThread clientThread,
        FairyRingOrganizerConfig config,
        FairyRingWidgetScanner scanner,
        FairyRingOrderService orderService,
        FairyRingLabelService labelService,
        FairyRingDragController dragController,
        FairyRingSearchController searchController,
        FairyRingNativeStateService nativeStateService,
        FairyRingFavoriteStateService favoriteStateService)
    {
        this.client = client;
        this.clientThread = clientThread;
        this.config = config;
        this.scanner = scanner;
        this.orderService = orderService;
        this.labelService = labelService;
        this.dragController = dragController;
        this.searchController = searchController;
        this.nativeStateService = nativeStateService;
        this.favoriteStateService = favoriteStateService;
    }

    /**
     * Marks the interface as active. Jagex can finish/rebuild the log after WidgetLoaded, so
     * a one-shot game-tick fallback is armed here. The script callback path can still apply
     * sooner when it is emitted, but the game-tick pass guarantees a final post-build layout.
     */
    public void onWidgetLoaded()
    {
        interfaceActive = true;

        // Reopening with an existing search is fundamentally different from a normal open:
        // Jagex is already responsible for compacting the filtered result set. Do not arm a
        // normal Organizer permutation that can briefly move those filtered widgets.
        if (searchController.isSearchActive() || searchController.isSearchInputPending())
        {
            enterSearchPresentation();
            initialRenderRefreshPending = false;
            refreshOnNextGameTick = false;
            return;
        }

        searchPresentationActive = false;
        // Do not wait for the next 600 ms game tick for the first Organizer layout.
        // BeforeRender runs after the interface-building client scripts but before the frame is
        // painted, giving us a chance to replace the native order before the player sees it.
        initialRenderRefreshPending = true;
        refreshOnNextGameTick = true;
    }

    /**
     * First-open fast path. The Configure widgets must exist before they can be sorted, so it is
     * impossible to reorder them before Jagex constructs them. What we can do is apply the first
     * permutation at RuneLite's BeforeRender boundary: after the construction scripts have run,
     * but before that frame is drawn. This removes the visible native-order -> Organizer-order
     * flash without weakening the slower GameTick safeguards used for in-place favorite rebuilds.
     */
    public void onBeforeRender()
    {
        if (!interfaceActive)
        {
            return;
        }

        // Search/filter presentation is native-owned. This is intentionally idempotent and
        // performs no sort/repack, so even if Jagex runs its filter script repeatedly while
        // the text box has focus there is nothing for the two layouts to fight over.
        if (searchController.isSearchActive() || searchController.isSearchInputPending())
        {
            enterSearchPresentation();
            initialRenderRefreshPending = false;
            refreshOnNextGameTick = false;
            refreshPending = false;
            return;
        }

        if (!initialRenderRefreshPending)
        {
            return;
        }

        refreshNow();

        // A successful scan/capture means the rows existed and were laid out. Cancel the
        // fallback/delayed pass so it cannot clear and reapply the same positions a frame later.
        if (nativeStateService.hasLiveState() && !waitForNativeGeometry)
        {
            initialRenderRefreshPending = false;
            refreshOnNextGameTick = false;
            refreshPending = false;
        }
    }

    /**
     * Called from the fairy-ring filter callbacks while Jagex is constructing list rows.
     *
     * If the interface is already Organizer-sorted, those still-live widgets can retain forced
     * coordinates while Jagex rebuilds the Favorites/Remaining membership after a heart click.
     * The build script then sees a mixture of native and Organizer geometry, and a later scan can
     * faithfully preserve that corrupted mixture. Clear our live presentation on the *first*
     * callback of each build burst so Jagex completes the rebuild against native coordinates.
     */
    public void onFairyRingBuildCallback()
    {
        interfaceActive = true;
        boolean searchActive = searchController.isSearchActive();
        boolean firstKeyPending = !searchActive && searchController.isSearchInputPending();

        if (searchActive || firstKeyPending)
        {
            // The filter callback can run repeatedly while the search field has focus. Enter
            // native-owned search presentation once, then leave every later callback alone.
            // firstKeyPending covers the one-frame gap before FAIRYRINGS_SEARCHSTRING updates,
            // but only after stripping RuneScape's otherwise-always-present '*' cursor marker.
            enterSearchPresentation();
            fairyBuildCallbackSeen = true;
            refreshOnNextGameTick = false;
            return;
        }

        if (searchPresentationActive)
        {
            // Search has just been cleared. Jagex is rebuilding the full native list now; wait
            // for this script to finish, then apply the saved Organizer order exactly once.
            searchPresentationActive = false;
            deferCurrentBuildToGameTick = false;
            waitForNativeGeometry = false;
            dragController.clear();
            nativeStateService.clearForcedPositions();
            clearDividerOverride();
            nativeStateService.clear();
            fairyBuildCallbackSeen = true;
            refreshOnNextGameTick = false;
            return;
        }

        if (!fairyBuildCallbackSeen)
        {
            // A favorite/unfavorite rebuilds the already-open log in place. If Organizer has
            // live state, do not race the middle of that rebuild. Clear our presentation
            // immediately, but defer the next permutation until the next GameTick so Jagex has
            // completed its native membership/layout pass first.
            deferCurrentBuildToGameTick = nativeStateService.hasLiveState();
            if (deferCurrentBuildToGameTick)
            {
                waitForNativeGeometry = true;
            }
            dragController.clear();
            nativeStateService.clearForcedPositions();
            clearDividerOverride();
            nativeStateService.clear();
        }

        fairyBuildCallbackSeen = true;
        refreshOnNextGameTick = true;
    }

    /**
     * ScriptPostFired is the earliest reliable point after the row-building callback's script
     * has completed. Coalesce all row callbacks into one post-script Organizer refresh.
     */
    public void onScriptPostFired()
    {
        if (!fairyBuildCallbackSeen)
        {
            return;
        }

        fairyBuildCallbackSeen = false;

        // Native search/filter layout is intentionally left untouched. ScriptPostFired can
        // happen many times while typing (including for whitespace); never enqueue a sort here.
        if (searchController.isSearchActive() || searchController.isSearchInputPending() || searchPresentationActive)
        {
            return;
        }

        if (deferCurrentBuildToGameTick)
        {
            // Keep refreshOnNextGameTick armed. An immediate invokeLater refresh here is early
            // enough to catch partially compacted rows when a Favorite is removed.
            deferCurrentBuildToGameTick = false;
            return;
        }

        refreshSoon();
    }

    /**
     * Update only destination labels while Jagex owns an active Fairy Ring search. This must not
     * sort, move, hide, or otherwise compact rows: the native search script remains the sole
     * owner of filtered-list geometry. After this repaint the rename controller reopens the
     * current search, causing the normal filter callbacks to re-evaluate membership against the
     * updated effective name.
     */
    public void refreshLabelsDuringSearch()
    {
        if (!searchController.isSearchActive() && !searchController.isSearchInputPending())
        {
            refreshNow();
            return;
        }

        Widget favorites = client.getWidget(InterfaceID.FairyringsLog.FAVES);
        Widget remaining = client.getWidget(InterfaceID.FairyringsLog.CONTENTS);
        if (!isVisible(favorites) && !isVisible(remaining))
        {
            return;
        }

        List<FairyRingRow> favoriteRows = scanner.scan(favorites, FairyRingSection.FAVORITES);
        Set<String> favoriteCodes = favoriteRows.stream()
            .map(FairyRingRow::getCode)
            .collect(Collectors.toSet());
        List<FairyRingRow> remainingRows = scanner.scan(remaining, FairyRingSection.REMAINING);
        remainingRows.removeIf(row -> favoriteCodes.contains(row.getCode()));

        for (FairyRingRow row : favoriteRows)
        {
            applyLabel(row);
        }
        for (FairyRingRow row : remainingRows)
        {
            applyLabel(row);
        }

        if (favorites != null)
        {
            favorites.revalidateScroll();
        }
        if (remaining != null)
        {
            remaining.revalidateScroll();
        }
    }

    /**
     * Fast path for a user changing one section's sort mode while Configure is already open.
     * Reuses the settled rows/spans cached by the drag controller and never clears the untouched
     * section, preventing the native-heart/Remaining flicker caused by a full refresh.
     */
    public boolean applySortModeChange(FairyRingSection section)
    {
        if (!interfaceActive || waitForNativeGeometry || fairyBuildCallbackSeen
            || searchPresentationActive || searchController.isSearchActive()
            || searchController.isSearchInputPending())
        {
            return false;
        }

        SortMode mode = section == FairyRingSection.FAVORITES
            ? config.favoriteSort()
            : config.remainingSort();
        boolean dragAllowed = !searchPresentationActive
            && !searchController.isSearchActive()
            && !searchController.isSearchInputPending();
        return dragController.applySortModeLocally(section, mode, dragAllowed);
    }

    /** Coalesces many Jagex list-building callbacks into one post-script refresh. */
    public void refreshSoon()
    {
        if (refreshPending)
        {
            return;
        }

        refreshPending = true;
        clientThread.invokeLater(() -> clientThread.invokeLater(() -> {
            // The first-open BeforeRender path can satisfy/cancel this queued refresh before
            // it executes. Do not perform a redundant clear/rescan/reapply after that.
            if (!refreshPending)
            {
                return;
            }
            refreshPending = false;
            refreshNow();
        }));
    }

    public void refreshNow()
    {
        Widget favorites = client.getWidget(InterfaceID.FairyringsLog.FAVES);
        Widget remaining = client.getWidget(InterfaceID.FairyringsLog.CONTENTS);
        if (!isVisible(favorites) && !isVisible(remaining))
        {
            closeInterface();
            return;
        }

        interfaceActive = true;

        // Do not sort a filtered list. Jagex owns row visibility and compaction while any
        // search text exists; Organizer resumes only after the filter has been cleared.
        if (searchController.isSearchActive() || searchController.isSearchInputPending())
        {
            enterSearchPresentation();
            refreshOnNextGameTick = false;
            return;
        }
        searchPresentationActive = false;

        if (waitForNativeGeometry && !isNativeInterfaceSettled(favorites, remaining))
        {
            // Do not mutate anything while Jagex is still compacting an in-place rebuild.
            // A later GameTick will retry against the same untouched native widgets.
            refreshOnNextGameTick = true;
            return;
        }
        waitForNativeGeometry = false;

        // A previous Organizer order can leave forced coordinates on still-live widgets.
        // Clear those first so every refresh starts from Jagex's native geometry, then apply
        // exactly one fresh permutation. This is especially important when changing sort modes.
        nativeStateService.clearForcedPositions();
        clearDividerOverride();

        // Capture the native relationship between the Favorites rows, the dedicated divider,
        // and the first Remaining row before applying any custom label heights. A short custom
        // name can legitimately shrink a Favorites row (for example 44 -> 32px). Without moving
        // this section boundary in the same pass, Jagex's divider/Remaining rows briefly stay at
        // the old native Y and render as an empty gap until a later interface revalidation.
        SectionBoundary boundary = captureSectionBoundary(favorites, remaining);

        boolean dragAllowed = !searchPresentationActive
            && !searchController.isSearchActive()
            && !searchController.isSearchInputPending();
        SectionLayoutResult favoriteLayout = applySection(
            favorites, FairyRingSection.FAVORITES, config.favoriteSort(), dragAllowed,
            java.util.Collections.emptySet(), null);

        Integer remainingStartY = null;
        Integer targetDividerY = null;
        if (!waitForNativeGeometry && boundary != null && favoriteLayout.hasRows())
        {
            targetDividerY = favoriteLayout.getPackedEndY() + boundary.dividerOffsetFromFavoriteEnd;
            remainingStartY = targetDividerY + boundary.remainingOffsetFromDivider;
        }

        SectionLayoutResult remainingLayout = applySection(
            remaining, FairyRingSection.REMAINING, config.remainingSort(), dragAllowed,
            new HashSet<>(favoriteLayout.getCodes()), remainingStartY);

        // CONTENTS owns the combined scrolling extent. If Favorites changed height, force one
        // synchronous scroll-layout recomputation after both sections and the divider have their
        // final positions so the first rendered frame already has the settled section boundary.
        if (!waitForNativeGeometry && boundary != null && targetDividerY != null
            && remainingStartY != null && remainingLayout.hasRows())
        {
            applyDividerOverride(boundary.divider, targetDividerY);
            if (remainingStartY != boundary.nativeRemainingStartY && remaining != null)
            {
                remaining.revalidateScroll();
            }
        }
    }

    private SectionLayoutResult applySection(
        Widget container, FairyRingSection section, SortMode sortMode, boolean dragAllowed,
        Set<String> excludedCodes, Integer startYOverride)
    {
        List<FairyRingRow> rows = scanner.scan(container, section);
        if (excludedCodes != null && !excludedCodes.isEmpty())
        {
            rows.removeIf(row -> excludedCodes.contains(row.getCode()));
        }
        if (rows.isEmpty())
        {
            dragController.updateRows(section, new ArrayList<>(), sortMode, dragAllowed);
            return SectionLayoutResult.empty();
        }

        // Record the live pre-plugin presentation before moving or relabeling anything.
        // The snapshot is tied to the current Jagex container and can be restored on disable.
        nativeStateService.capture(section, container, rows);

        // Capture Jagex's label before this plugin potentially replaces it. This gives
        // future valid codes a fallback name even before our local enum is updated.
        for (FairyRingRow row : rows)
        {
            if (row.getLabelWidget() != null)
            {
                labelService.observeDefaultName(row.getCode(), row.getLabelWidget().getText());
            }
        }

        // Apply/reset destination text before measuring row footprints. Custom labels preserve
        // Jagex's native leading layout markup and auto-sizing, so a long label can grow the
        // destination widget downward without ever moving the three-letter code. Measuring after
        // this step lets Organizer expand following row slots only when the rendered label truly
        // needs more vertical room.
        for (FairyRingRow row : rows)
        {
            applyLabel(row);
        }

        // Preserve the *native row layout*, not just the old row starting coordinates.
        // Fairy-ring rows have variable heights because long destination names wrap. Reusing
        // the old slot starts after sorting can put a multi-line row into a shorter slot and
        // make later rows overlap. Capture each row's native vertical footprint, then pack the
        // sorted rows back-to-back using that row's own footprint.
        List<FairyRingRow> nativeRows = rows.stream()
            .sorted(Comparator.comparingInt(FairyRingRow::getBaseY))
            .collect(Collectors.toList());

        List<String> visibleCodes = nativeRows.stream()
            .map(FairyRingRow::getCode)
            .collect(Collectors.toList());

        List<String> sortedCodes = orderService.sortCodes(visibleCodes, section, sortMode);
        boolean positionsChange = !sortedCodes.equals(visibleCodes);
        Map<String, FairyRingRow> byCode = new HashMap<>();
        for (FairyRingRow row : rows)
        {
            byCode.put(row.getCode(), row);
        }

        Map<String, Integer> rowSpans = calculateNativeRowSpans(nativeRows);
        boolean dynamicSpanChange = hasDynamicSpanChange(nativeRows, rowSpans);

        // Final fail-safe: never convert transitional/native corruption into persistent forced
        // positions. Normal live Fairy Ring rows are 32/44 px in current Jagex layouts; allow
        // a broad 28..128 range for future wrapping, but reject the 8/24/488 style spans seen
        // during a partially rebuilt favorite transition; retry on the next game tick instead.
        if (!areCalculatedSpansSane(rowSpans))
        {
            waitForNativeGeometry = true;
            refreshOnNextGameTick = true;
            dragController.updateRows(section, new ArrayList<>(), sortMode, false);
            return new SectionLayoutResult(
                nativeRows.stream().map(FairyRingRow::getCode).collect(Collectors.toList()),
                nativeRows.get(0).getBaseY(),
                calculateCurrentSectionEnd(nativeRows));
        }

        int packedStartY = startYOverride == null
            ? nativeRows.get(0).getBaseY()
            : startYOverride;
        boolean sectionStartChange = packedStartY != nativeRows.get(0).getBaseY();
        int nextY = packedStartY;
        List<FairyRingRow> sortedRows = new ArrayList<>();
        for (String code : sortedCodes)
        {
            FairyRingRow row = byCode.get(code);
            if (row == null)
            {
                continue;
            }

            if (positionsChange || dynamicSpanChange || sectionStartChange)
            {
                row.moveTo(nextY);
            }
            sortedRows.add(row);
            nextY += rowSpans.getOrDefault(code, 32);
        }

        // Record exactly what this plugin applied. A future capture can then distinguish
        // our own state from a new native/Jagex rebuild on the same Widget objects.
        nativeStateService.recordApplied(section, sortedRows);

        // A custom label may legitimately add another wrapped line. Recompute the scrollable
        // extent only in that case so rows moved below the old native content height remain
        // reachable without adding work to ordinary refreshes. Forced positions survive this
        // revalidation.
        if (dynamicSpanChange && container != null)
        {
            container.revalidateScroll();
        }

        // Searching can temporarily expose only a subset of rows. The list remains sorted,
        // but manual drag is disabled until the filter is empty so a subset can never be
        // accidentally persisted as the whole manual order.
        dragController.updateRows(section, sortedRows, sortMode, dragAllowed, rowSpans);
        return new SectionLayoutResult(
            sortedRows.stream().map(FairyRingRow::getCode).collect(Collectors.toList()),
            packedStartY,
            nextY);
    }

    /**
     * Capture the live native section boundary before Organizer changes custom row heights.
     * FairyringsLog exposes a dedicated DIVIDER widget between FAVES and CONTENTS; keeping the
     * existing native offsets around that divider lets this stay robust if Jagex changes the
     * exact number of pixels between the two sections.
     */
    private SectionBoundary captureSectionBoundary(Widget favorites, Widget remaining)
    {
        Widget divider = client.getWidget(InterfaceID.FairyringsLog.DIVIDER);
        if (!isVisible(divider) || !isVisible(favorites) || !isVisible(remaining))
        {
            return null;
        }

        List<FairyRingRow> favoriteRows = scanner.scan(favorites, FairyRingSection.FAVORITES).stream()
            .sorted(Comparator.comparingInt(FairyRingRow::getBaseY))
            .collect(Collectors.toList());
        if (favoriteRows.isEmpty())
        {
            return null;
        }

        Set<String> favoriteCodes = favoriteRows.stream()
            .map(FairyRingRow::getCode)
            .collect(Collectors.toSet());
        List<FairyRingRow> remainingRows = scanner.scan(remaining, FairyRingSection.REMAINING).stream()
            .filter(row -> !favoriteCodes.contains(row.getCode()))
            .sorted(Comparator.comparingInt(FairyRingRow::getBaseY))
            .collect(Collectors.toList());
        if (remainingRows.isEmpty())
        {
            return null;
        }

        int nativeFavoriteEndY = calculateCurrentSectionEnd(favoriteRows);
        int nativeDividerY = FairyRingWidgetScanner.effectiveRelativeY(divider);
        int nativeRemainingStartY = remainingRows.get(0).getBaseY();

        return new SectionBoundary(
            divider,
            nativeDividerY - nativeFavoriteEndY,
            nativeRemainingStartY - nativeDividerY,
            nativeRemainingStartY);
    }

    /**
     * Current section end using the live pre-Organizer row geometry. The last row has no next-row
     * start from which to derive its span, so use its rendered row footprint plus Jagex's normal
     * 3px trailing spacing (29 -> 32, 41 -> 44).
     */
    private static int calculateCurrentSectionEnd(List<FairyRingRow> rows)
    {
        if (rows == null || rows.isEmpty())
        {
            return 0;
        }

        List<FairyRingRow> ordered = rows.stream()
            .sorted(Comparator.comparingInt(FairyRingRow::getBaseY))
            .collect(Collectors.toList());
        FairyRingRow last = ordered.get(ordered.size() - 1);
        return last.getBaseY() + Math.max(32, last.getLogicalHeight() + 3);
    }

    private void applyDividerOverride(Widget divider, int targetY)
    {
        if (divider == null)
        {
            return;
        }

        int x = FairyRingWidgetScanner.effectiveRelativeX(divider);
        if (FairyRingWidgetScanner.effectiveRelativeY(divider) != targetY)
        {
            divider.setForcedPosition(x, targetY);
            dividerOverrideWidget = divider;
        }
    }

    private void clearDividerOverride()
    {
        if (dividerOverrideWidget == null)
        {
            return;
        }

        dividerOverrideWidget.setForcedPosition(-1, -1);
        dividerOverrideWidget.revalidate();
        dividerOverrideWidget = null;
    }

    private static final class SectionBoundary
    {
        private final Widget divider;
        private final int dividerOffsetFromFavoriteEnd;
        private final int remainingOffsetFromDivider;
        private final int nativeRemainingStartY;

        private SectionBoundary(
            Widget divider,
            int dividerOffsetFromFavoriteEnd,
            int remainingOffsetFromDivider,
            int nativeRemainingStartY)
        {
            this.divider = divider;
            this.dividerOffsetFromFavoriteEnd = dividerOffsetFromFavoriteEnd;
            this.remainingOffsetFromDivider = remainingOffsetFromDivider;
            this.nativeRemainingStartY = nativeRemainingStartY;
        }
    }

    private static final class SectionLayoutResult
    {
        private final List<String> codes;
        private final int packedStartY;
        private final int packedEndY;

        private SectionLayoutResult(List<String> codes, int packedStartY, int packedEndY)
        {
            this.codes = codes;
            this.packedStartY = packedStartY;
            this.packedEndY = packedEndY;
        }

        private static SectionLayoutResult empty()
        {
            return new SectionLayoutResult(java.util.Collections.emptyList(), 0, 0);
        }

        private List<String> getCodes()
        {
            return codes;
        }

        private int getPackedEndY()
        {
            return packedEndY;
        }

        private boolean hasRows()
        {
            return !codes.isEmpty() && packedEndY > packedStartY;
        }
    }

    /**
     * During an in-place Favorite rebuild RuneLite can expose old row widgets with relative
     * coordinates of -1 until Jagex finishes revalidation. Applying a
     * permutation during that window corrupts the row spans. Wait until every visible member
     * widget has real rendered coordinates and both sections have plausible row spacing.
     */
    private boolean isNativeInterfaceSettled(Widget favorites, Widget remaining)
    {
        List<FairyRingRow> favoriteRows = scanner.scan(favorites, FairyRingSection.FAVORITES);
        Set<String> favoriteCodes = favoriteRows.stream()
            .map(FairyRingRow::getCode)
            .collect(Collectors.toSet());
        List<FairyRingRow> remainingRows = scanner.scan(remaining, FairyRingSection.REMAINING);
        remainingRows.removeIf(row -> favoriteCodes.contains(row.getCode()));

        boolean settled = isRenderedGeometrySettled(favoriteRows)
            && isRenderedGeometrySettled(remainingRows)
            && isNativeGeometrySane(favoriteRows.stream()
                .sorted(Comparator.comparingInt(FairyRingRow::getBaseY))
                .collect(Collectors.toList()))
            && isNativeGeometrySane(remainingRows.stream()
                .sorted(Comparator.comparingInt(FairyRingRow::getBaseY))
                .collect(Collectors.toList()));

        return settled;
    }

    private static boolean isRenderedGeometrySettled(List<FairyRingRow> rows)
    {
        for (FairyRingRow row : rows)
        {
            for (Widget widget : row.getMemberWidgets())
            {
                if (widget == null || widget.isSelfHidden())
                {
                    continue;
                }
                if (widget.getRelativeX() < 0 || widget.getRelativeY() < 0)
                {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Healthy Fairy Ring rows occupy distinct, monotonically increasing native slots. Current
     * rows use 32/44 px spacing; allow a generous 12..128 px window for future wrapping while
     * rejecting duplicate, 1 px, or implausibly large transitional rebuild geometry.
     */
    private static boolean isNativeGeometrySane(List<FairyRingRow> nativeRows)
    {
        if (nativeRows == null || nativeRows.size() <= 1)
        {
            return true;
        }

        for (int i = 0; i + 1 < nativeRows.size(); i++)
        {
            int gap = nativeRows.get(i + 1).getBaseY() - nativeRows.get(i).getBaseY();
            if (gap < 12 || gap > 128)
            {
                return false;
            }
        }
        return true;
    }

    /**
     * Calculate the vertical slot each row should own. Untouched/reset rows use the Jagex height
     * captured before Organizer changes anything. Custom rows instead use the current measured
     * text footprint, so replacing a two-line native destination with a one-line custom name can
     * legitimately shrink 44 -> 32, while a wrapped custom label can grow 32 -> 44 -> 56.
     *
     * Fairy-ring rows use three pixels of trailing space after their text widgets (29 -> 32 and
     * 41 -> 44 in the live layouts).
     */
    private Map<String, Integer> calculateNativeRowSpans(List<FairyRingRow> nativeRows)
    {
        Map<String, Integer> spans = new HashMap<>();

        for (int i = 0; i < nativeRows.size(); i++)
        {
            FairyRingRow row = nativeRows.get(i);
            int currentSpan;
            if (i + 1 < nativeRows.size())
            {
                currentSpan = Math.max(1, nativeRows.get(i + 1).getBaseY() - row.getBaseY());
            }
            else
            {
                currentSpan = spans.isEmpty() ? 32 : median(new ArrayList<>(spans.values()));
            }

            int nativeLabelHeight = nativeStateService.getNativeLabelRenderedHeight(row.getCode());
            int nativeBaselineSpan = nativeLabelHeight > 0
                ? nativeLabelHeight + 3
                : currentSpan;

            // Native Jagex rows keep their original 32/44px footprint. A user-supplied label is
            // different: its footprint is content-driven, so a one-line custom name is allowed
            // to shrink a ring whose original destination occupied two lines. applyLabel() has
            // already synchronized both text widgets to the calculated custom height, therefore
            // getLogicalHeight() is the current custom footprint rather than stale native height.
            boolean hasCustomLabel = config.renameInterfaceRows()
                && labelService.getOwnCustomLabel(row.getCode()) != null;
            int logicalHeight = row.getLogicalHeight();
            int desiredSpan;
            if (hasCustomLabel)
            {
                desiredSpan = logicalHeight > 0 ? Math.max(32, logicalHeight + 3) : 32;
            }
            else
            {
                desiredSpan = nativeBaselineSpan;
            }

            spans.put(row.getCode(), desiredSpan);
        }

        return spans;
    }

    private static boolean hasDynamicSpanChange(List<FairyRingRow> nativeRows, Map<String, Integer> spans)
    {
        for (int i = 0; i + 1 < nativeRows.size(); i++)
        {
            FairyRingRow row = nativeRows.get(i);
            int currentSpan = Math.max(1, nativeRows.get(i + 1).getBaseY() - row.getBaseY());
            if (spans.getOrDefault(row.getCode(), currentSpan) != currentSpan)
            {
                return true;
            }
        }
        return false;
    }

    private static boolean areCalculatedSpansSane(Map<String, Integer> spans)
    {
        if (spans == null || spans.isEmpty())
        {
            return true;
        }

        for (Integer span : spans.values())
        {
            if (span == null || span < 28 || span > 128)
            {
                return false;
            }
        }
        return true;
    }

    private static int median(List<Integer> values)
    {
        if (values.isEmpty())
        {
            return 0;
        }
        values.sort(Integer::compareTo);
        return values.get(values.size() / 2);
    }

    private void applyLabel(FairyRingRow row)
    {
        if (row.getLabelWidget() == null)
        {
            return;
        }

        // "Show custom names in list" should only replace Jagex's label when the user has
        // actually created a custom label. Known catalogue names are used for sorting/search,
        // but they must not silently replace the native Configure text/category formatting.
        String customLabel = config.renameInterfaceRows() ? labelService.getOwnCustomLabel(row.getCode()) : null;
        if (customLabel == null)
        {
            nativeStateService.restoreLabel(row.getSection(), row.getCode(), row.getLabelWidget());
            nativeStateService.restoreRowTextHeight(row.getSection(), row);
            return;
        }

        nativeStateService.applyLabelPreservingNativeLayout(
            row.getSection(), row.getCode(), row.getLabelWidget(), customLabel);

        // The Fairy Ring code widget and destination widget share one rendered row height. Jagex
        // normally bakes that height into the interface (29px for code + one destination line,
        // 41px for code + two destination lines). Replacing a two-line native destination with
        // "Beach" must therefore reduce both text widgets to the one-line height; preserving the
        // keeping the old native height would leave an apparently-empty second row.
        int customTextHeight = calculateCustomRowTextHeight(row.getLabelWidget(), customLabel);
        nativeStateService.applyDynamicRowTextHeight(row.getSection(), row, customTextHeight);

    }

    /**
     * Measure the custom destination using the actual RuneScape font and live widget width. The
     * first line belongs to the three-letter code, so total row height is one code line plus the
     * number of destination lines needed by the custom text. We wrap only at whitespace, matching
     * the behavior users expect from normal fairy-ring labels; a single long token stays on one
     * line instead of manufacturing an extra blank row.
     */
    private static int calculateCustomRowTextHeight(Widget labelWidget, String customLabel)
    {
        if (labelWidget == null)
        {
            return 29;
        }

        FontTypeFace font = labelWidget.getFont();
        int lineHeight = labelWidget.getLineHeight();
        if (lineHeight <= 0 && font != null)
        {
            lineHeight = font.getBaseline();
        }
        if (lineHeight <= 0)
        {
            lineHeight = 12;
        }

        int width = labelWidget.getWidth();
        if (width <= 0)
        {
            width = Math.max(1, labelWidget.getOriginalWidth());
        }

        int destinationLines = measureWrappedLineCount(font, customLabel, width);

        // Live Fairy Ring text widgets consistently include ~5px of vertical padding around the
        // line grid (29px for 2 total lines, 41px for 3). Preserve that presentation while making
        // the number of destination lines content-driven.
        int verticalPadding = 5;
        return Math.max(29, verticalPadding + lineHeight * (1 + destinationLines));
    }

    private static int measureWrappedLineCount(FontTypeFace font, String text, int width)
    {
        if (text == null || text.trim().isEmpty() || font == null || width <= 0)
        {
            return 1;
        }

        String[] words = text.trim().split("\\s+");
        int lines = 1;
        String current = "";

        for (String word : words)
        {
            if (current.isEmpty())
            {
                current = word;
                continue;
            }

            String candidate = current + " " + word;
            if (font.getTextWidth(candidate) <= width)
            {
                current = candidate;
            }
            else
            {
                lines++;
                current = word;
            }
        }

        return Math.max(1, lines);
    }

    /**
     * One-shot post-build fallback. The live client can create/revalidate the fairy-ring rows
     * after WidgetLoaded without producing a callback sequence we can reliably key from.
     * Waiting until the next game tick gives Jagex one full build cycle, then the flag is cleared.
     */
    public void onGameTick()
    {
        if (!refreshOnNextGameTick || !interfaceActive)
        {
            return;
        }

        refreshOnNextGameTick = false;
        refreshNow();
    }

    /**
     * Called once per game tick while Configure is open. Membership changes are debounced
     * so a newly favorited ring is appended to the bottom of the saved Favorites order.
     */
    public void observeFavoriteMembership()
    {
        // Search can temporarily hide/filter rows, so never interpret a filtered view as
        // a real favorite/unfavorite membership transition.
        if (searchPresentationActive || searchController.isSearchActive()
            || searchController.isSearchInputPending())
        {
            return;
        }

        Widget favorites = client.getWidget(InterfaceID.FairyringsLog.FAVES);
        if (favorites == null || favorites.isHidden())
        {
            return;
        }

        List<String> codes = scanner.scan(favorites, FairyRingSection.FAVORITES).stream()
            .sorted(Comparator.comparingInt(FairyRingRow::getBaseY))
            .map(FairyRingRow::getCode)
            .collect(Collectors.toList());

        if (favoriteStateService.observe(codes))
        {
            refreshSoon();
        }
    }

    /**
     * Cheap per-client-frame lifecycle hook. When inactive it does no widget lookups. While
     * Configure is active it checks only the two section containers, and the drag controller
     * performs deeper work only if their scroll/layout signature changed.
     */
    public void onClientTick()
    {
        if (!interfaceActive)
        {
            return;
        }

        Widget remaining = client.getWidget(InterfaceID.FairyringsLog.CONTENTS);
        Widget favorites = client.getWidget(InterfaceID.FairyringsLog.FAVES);
        if (!isVisible(remaining) && !isVisible(favorites))
        {
            closeInterface();
            return;
        }

        if (searchPresentationActive || searchController.isSearchActive()
            || searchController.isSearchInputPending())
        {
            return;
        }

        dragController.refreshHandleBoundsIfLayoutChanged();
    }

    private void enterSearchPresentation()
    {
        if (searchPresentationActive)
        {
            return;
        }

        searchPresentationActive = true;
        deferCurrentBuildToGameTick = false;
        waitForNativeGeometry = false;
        dragController.clear();

        // Remove only Organizer's coordinate overrides. The native filter script then owns the
        // compacted result positions, which prevents Edgeville/single-result rows and their
        // heart graphics from being pulled back toward full-list Manual/Code slots.
        nativeStateService.clearForcedPositions();
        clearDividerOverride();
        nativeStateService.clear();

    }

    private void closeInterface()
    {
        refreshPending = false;
        initialRenderRefreshPending = false;
        fairyBuildCallbackSeen = false;
        refreshOnNextGameTick = false;
        deferCurrentBuildToGameTick = false;
        waitForNativeGeometry = false;
        searchPresentationActive = false;
        dragController.clear();
        // The containers are already hidden, so clearing Organizer-owned coordinates here cannot
        // flash. It also prevents stale full-list positions from surviving into a searched reopen.
        nativeStateService.clearForcedPositions();
        clearDividerOverride();
        nativeStateService.clearAll();
        favoriteStateService.reset();
        interfaceActive = false;
    }

    private static boolean isVisible(Widget widget)
    {
        return widget != null && !widget.isHidden();
    }

    /** Restores the currently open interface to the state captured before this plugin edited it. */
    public void restoreNative()
    {
        refreshPending = false;
        initialRenderRefreshPending = false;
        fairyBuildCallbackSeen = false;
        refreshOnNextGameTick = false;
        deferCurrentBuildToGameTick = false;
        waitForNativeGeometry = false;
        searchPresentationActive = false;
        dragController.clear();
        clearDividerOverride();
        nativeStateService.restoreAll();
        favoriteStateService.reset();
        interfaceActive = false;
    }

    /** Clears transient snapshots/state without touching saved Organizer preferences. */
    public void resetRuntimeState()
    {
        refreshPending = false;
        initialRenderRefreshPending = false;
        fairyBuildCallbackSeen = false;
        refreshOnNextGameTick = false;
        deferCurrentBuildToGameTick = false;
        waitForNativeGeometry = false;
        searchPresentationActive = false;
        dragController.clear();
        clearDividerOverride();
        nativeStateService.clearAll();
        favoriteStateService.reset();
        interfaceActive = false;
    }

    public boolean isOpen()
    {
        return interfaceActive;
    }
}

package com.fairyringorganizer;

import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.Text;

/** Resolves/sanitizes local display names and persists them only through RuneLite ConfigManager. */
@Singleton
public class FairyRingLabelService
{
    public static final int MAX_CUSTOM_LABEL_LENGTH = 40;
    private static final int MAX_OBSERVED_NAME_LENGTH = 120;

    private final ConfigManager configManager;

    // Fallback names observed directly from Jagex's Configure rows. This lets a newly
    // added valid fairy-ring code work before FairyRingDestination is updated.
    private final Map<String, String> observedDefaultNames = new ConcurrentHashMap<>();

    // Effective labels are read frequently by sorting, search callbacks, and menu presentation.
    // Cache them so those hot paths do not repeatedly hit ConfigManager and sanitize strings.
    private final Map<String, String> effectiveNameCache = new ConcurrentHashMap<>();

    @Inject
    public FairyRingLabelService(ConfigManager configManager)
    {
        this.configManager = configManager;
    }

    /** Priority: Organizer custom label -> known destination -> observed Jagex name -> code. */
    public String getEffectiveName(String code)
    {
        String normalized = FairyRingOrderService.normalizeCode(code);
        if (!FairyRingDestination.isValidCode(normalized))
        {
            return normalized;
        }
        return effectiveNameCache.computeIfAbsent(normalized, this::resolveEffectiveName);
    }

    private String resolveEffectiveName(String normalized)
    {
        String own = getOwnCustomLabel(normalized);
        if (own != null)
        {
            return own;
        }

        FairyRingDestination destination = FairyRingDestination.forCode(normalized);
        if (destination != null)
        {
            return destination.getDestination();
        }

        return observedDefaultNames.getOrDefault(normalized, normalized);
    }

    /**
     * Captures Jagex's own row label before this plugin replaces it. Known catalogue
     * entries are ignored because their stable local name is preferred.
     */
    public void observeDefaultName(String code, String widgetText)
    {
        String normalized = FairyRingOrderService.normalizeCode(code);
        if (!FairyRingDestination.isValidCode(normalized) || FairyRingDestination.forCode(normalized) != null)
        {
            return;
        }

        String clean = sanitizeDisplayText(widgetText, MAX_OBSERVED_NAME_LENGTH);
        if (!clean.isEmpty() && !clean.equalsIgnoreCase(normalized)
            && observedDefaultNames.putIfAbsent(normalized, clean) == null)
        {
            effectiveNameCache.remove(normalized);
        }
    }

    public String getOwnCustomLabel(String code)
    {
        String normalized = FairyRingOrderService.normalizeCode(code);
        if (!FairyRingDestination.isValidCode(normalized))
        {
            return null;
        }

        String value = configManager.getConfiguration(FairyRingOrganizerConfig.LABEL_GROUP, normalized);
        if (value == null)
        {
            return null;
        }

        value = sanitizeCustomLabel(value);
        return value.isEmpty() ? null : value;
    }

    public void setOwnCustomLabel(String code, String label)
    {
        String normalized = FairyRingOrderService.normalizeCode(code);
        if (!FairyRingDestination.isValidCode(normalized))
        {
            return;
        }

        String clean = sanitizeCustomLabel(label);
        if (clean.isEmpty())
        {
            configManager.unsetConfiguration(FairyRingOrganizerConfig.LABEL_GROUP, normalized);
        }
        else
        {
            configManager.setConfiguration(FairyRingOrganizerConfig.LABEL_GROUP, normalized, clean);
        }
        effectiveNameCache.remove(normalized);
    }

    /**
     * Recover a code from a human-readable menu label after another presentation plugin has
     * already replaced the original bare code. Known catalogue aliases are supported, and
     * live Jagex names learned from Configure are accepted as a second compatibility path.
     */
    public String resolveCodeFromDisplayLabel(String displayLabel)
    {
        String clean = sanitizeDisplayText(displayLabel, MAX_OBSERVED_NAME_LENGTH);
        if (clean.isEmpty())
        {
            return null;
        }

        FairyRingDestination known = FairyRingDestination.forDisplayAlias(clean);
        if (known != null)
        {
            return known.getCode();
        }

        String resolved = null;
        for (Map.Entry<String, String> entry : observedDefaultNames.entrySet())
        {
            if (!entry.getValue().equalsIgnoreCase(clean))
            {
                continue;
            }

            // Do not guess if two future/native rows ever expose the exact same display name.
            if (resolved != null && !resolved.equals(entry.getKey()))
            {
                return null;
            }
            resolved = entry.getKey();
        }
        return resolved;
    }

    public void clearOwnCustomLabel(String code)
    {
        setOwnCustomLabel(code, null);
    }

    public void clearAllOwnLabels()
    {
        // Clear every current/future label key instead of only codes compiled into the enum.
        // ConfigManager returns flattened keys such as "fairyringorganizer.labels.DKR".
        List<String> keys = configManager.getConfigurationKeys(FairyRingOrganizerConfig.LABEL_GROUP + ".");
        for (String key : keys)
        {
            int lastDot = key.lastIndexOf('.');
            if (lastDot <= 0 || lastDot >= key.length() - 1)
            {
                continue;
            }

            configManager.unsetConfiguration(key.substring(0, lastDot), key.substring(lastDot + 1));
        }
        observedDefaultNames.clear();
        effectiveNameCache.clear();
    }

    public void invalidateAll()
    {
        effectiveNameCache.clear();
    }

    /**
     * Removes Jagex/RuneLite markup, control characters, repeated whitespace, and caps
     * labels at a UI-friendly length. Punctuation and normal Unicode text are retained.
     */
    public static String sanitizeCustomLabel(String label)
    {
        return sanitizeDisplayText(label, MAX_CUSTOM_LABEL_LENGTH);
    }

    private static String sanitizeDisplayText(String value, int maxLength)
    {
        if (value == null)
        {
            return "";
        }

        String clean = Text.removeTags(value)
            .replaceAll("[\\p{Cntrl}&&[^\\t\\n\\r]]", "")
            .replaceAll("[\\t\\n\\r]+", " ")
            .replaceAll("\\s{2,}", " ")
            .trim();

        int codePoints = clean.codePointCount(0, clean.length());
        if (codePoints > maxLength)
        {
            int end = clean.offsetByCodePoints(0, maxLength);
            clean = clean.substring(0, end).trim();
        }
        return clean;
    }

}

package com.fairyringorganizer;

import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.PostMenuSort;
import net.runelite.client.eventbus.Subscribe;

/**
 * Early menu-phase subscriber used only to capture raw fairy-ring menu identity before
 * Menu Entry Swapper and the Organizer's late presentation pass modify visible entries.
 *
 * RuneLite's EventBus requires subscribed methods to be named on<EventClass>. Keeping
 * these early handlers on a separate subscriber lets the main plugin retain its own
 * correctly named late handlers for the same event types at a lower priority.
 */
public class FairyRingMenuCaptureSubscriber
{
    private final Client client;
    private final FairyRingMenuController menuController;

    @Inject
    public FairyRingMenuCaptureSubscriber(Client client, FairyRingMenuController menuController)
    {
        this.client = client;
        this.menuController = menuController;
    }

    @Subscribe(priority = 1)
    public void onPostMenuSort(PostMenuSort event)
    {
        if (!client.isMenuOpen())
        {
            menuController.prepareCaptureIfRelevant(false);
        }
    }

    @Subscribe(priority = 1)
    public void onMenuOpened(MenuOpened event)
    {
        menuController.prepareCaptureIfRelevant(true);
    }
}

package com.fairyringorganizer;

import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

/**
 * Changes the presentation/order of the existing Fairy Ring menu while preserving
 * RuneLite/Jagex action semantics. It adds only RUNELITE-local configuration entries; it never
 * adds a new menu entry whose callback sends a game action. Per-ring overrides reuse an existing
 * root action slot, and Organizer never invokes the copied Favorite/teleport action itself.
 */
public class FairyRingMenuController
{
    private static final Pattern BARE_CODE = Pattern.compile("^([A-D][I-L][P-S])$");
    private static final Pattern CODE_IN_PARENS = Pattern.compile(".*\\(([A-D][I-L][P-S])\\)\\s*$");
    private static final Pattern LAST_DESTINATION = Pattern.compile(
        "^Last-destination \\(([A-D][I-L][P-S])\\)$",
        Pattern.CASE_INSENSITIVE);

    private final Client client;
    private final FairyRingOrganizerConfig config;
    private final FairyRingOrderService orderService;
    private final FairyRingLabelService labelService;
    private final FairyRingColorService colorService;
    private final FairyRingQuickDestinationService quickDestinationService;

    // Identity-by-object cache: continue recognizing the same existing MenuEntry after
    // the Organizer changes its visible option from DKR to "GE". The cache is
    // reset at the beginning of each menu build/open, so old menu objects do not accumulate.
    private final Map<MenuEntry, String> menuEntryCodes = new IdentityHashMap<>();
    private String recentDestinationCode;
    private boolean fairyMenuSeen;
    private boolean captureActive;
    private List<String> favoriteCodesSnapshot = new ArrayList<>();

    @Inject
    public FairyRingMenuController(
        Client client,
        FairyRingOrganizerConfig config,
        FairyRingOrderService orderService,
        FairyRingLabelService labelService,
        FairyRingColorService colorService,
        FairyRingQuickDestinationService quickDestinationService)
    {
        this.client = client;
        this.config = config;
        this.orderService = orderService;
        this.labelService = labelService;
        this.colorService = colorService;
        this.quickDestinationService = quickDestinationService;
    }

    /** Very cheap MenuEntryAdded gate used to keep PostMenuSort dormant elsewhere. */
    public void observeMenuEntryAdded(MenuEntry entry)
    {
        if (entry == null)
        {
            return;
        }

        boolean fairyRingEntry = isFairyRingEntry(entry);
        if (fairyRingEntry)
        {
            fairyMenuSeen = true;
        }

        // Capture identity on the MenuEntry object itself as soon as RuneLite creates it.
        // This survives another plugin replacing the visible option text later in the same
        // menu build. Submenu entries commonly arrive after their Fairy Ring parent, so once
        // this menu is known to be relevant we can safely learn any valid bare fairy code.
        if (fairyRingEntry || fairyMenuSeen)
        {
            String code = extractCode(entry.getOption());
            if (code != null)
            {
                rememberCode(entry, code);
            }
        }
    }

    /**
     * Called in the early menu phase. PostMenuSort uses only the MenuEntryAdded flag so
     * unrelated menus stay O(1); MenuOpened may enable the root fallback for timing safety.
     */
    public boolean prepareCaptureIfRelevant(boolean allowRootFallback)
    {
        if (!fairyMenuSeen)
        {
            if (!allowRootFallback || !rootContainsFairyRing())
            {
                captureActive = false;
                return false;
            }

            // MenuOpened commonly follows the already-processed PostMenuSort for the same
            // MenuEntry objects. Preserve their code identities so a code-hidden label such
            // as "Grand Exchange" does not become unrecognizable at open time.
            if (currentMenuContainsCachedIdentity())
            {
                captureActive = true;
                captureCodes();
                return true;
            }
        }

        captureActive = true;
        beginCapture();
        return true;
    }

    /** Called in the late menu phase after Menu Entry Swapper and other menu builders. */
    public void processPendingMenu()
    {
        if (!captureActive && !fairyMenuSeen)
        {
            return;
        }

        try
        {
            if (!captureActive)
            {
                beginCapture();
            }
            processMenus();
        }
        finally
        {
            fairyMenuSeen = false;
            captureActive = false;
        }
    }

    private boolean rootContainsFairyRing()
    {
        for (MenuEntry entry : client.getMenu().getMenuEntries())
        {
            if (isFairyRingEntry(entry))
            {
                return true;
            }
        }
        return false;
    }

    private boolean currentMenuContainsCachedIdentity()
    {
        for (MenuEntry entry : client.getMenu().getMenuEntries())
        {
            if (entryTreeContainsCachedIdentity(entry))
            {
                return true;
            }
        }
        return false;
    }

    private boolean entryTreeContainsCachedIdentity(MenuEntry entry)
    {
        if (menuEntryCodes.containsKey(entry))
        {
            return true;
        }
        Menu submenu = entry.getSubMenu();
        if (submenu == null)
        {
            return false;
        }
        for (MenuEntry child : submenu.getMenuEntries())
        {
            if (entryTreeContainsCachedIdentity(child))
            {
                return true;
            }
        }
        return false;
    }

    /**
     * Starts a fresh menu identity snapshot and captures raw fairy-ring codes before the
     * Organizer or other presentation plugins change visible menu text.
     */
    private void beginCapture()
    {
        menuEntryCodes.clear();
        // Keep the recent code across multiple presentation passes for the same menu. A fresh
        // native Last-destination entry will overwrite it during captureCodes().
        captureCodes();
    }

    /** Safe to call repeatedly within the same menu build. */
    public void captureCodes()
    {
        Menu root = client.getMenu();
        for (MenuEntry entry : root.getMenuEntries())
        {
            String target = Text.removeTags(nullToEmpty(entry.getTarget())).toLowerCase(Locale.ROOT);
            if (target.contains("fairy ring"))
            {
                captureEntryTree(entry);
            }
        }
    }

    private void processMenus()
    {
        // Also capture here so entries created later in the menu-build pipeline are learned.
        captureCodes();

        Menu root = client.getMenu();

        // Capture the remembered destination before any presentation filtering removes its
        // Last-destination row. Keep the value for later passes over the same open menu, where
        // the Last row may already have been filtered out by an earlier Organizer pass.
        String currentRecentCode = findLastDestinationCode(root);
        if (currentRecentCode != null)
        {
            recentDestinationCode = currentRecentCode;
        }
        else if (!config.hideRecentDestination())
        {
            // With Hide recent disabled, a missing Last entry is real rather than the result
            // of our own filtering, so do not carry a stale destination into Favourites.
            recentDestinationCode = null;
        }
        currentRecentCode = recentDestinationCode;

        // Preserve the complete current Favorites membership before Hide recent removes any
        // presentation-only row. The per-ring selector uses this snapshot so a temporarily
        // hidden recent favorite is still available as a choice.
        snapshotFavoriteCodes(root);

        // Per-ring quick destinations reuse the existing native Fairy Ring root action slot.
        // If Configure currently occupies that slot, applyPerRingQuickDestination preserves a
        // root-owned Configure copy before reusing the original slot for the ring-local Favorite.
        // MES's persisted global object swap is never changed here.
        if (config.perRingFavorites())
        {
            applyPerRingQuickDestination(root);
        }

        // Menu Entry Swapper creates separate RUNELITE-only "Swap left-click" and
        // "Swap shift-click" submenus. Give their destination choices the same Organizer
        // presentation as the action-bearing fairy-ring entries. This dedicated pass changes
        // only the visible option text; MES keeps its original onClick callback and swap index.
        if (config.labelMenus())
        {
            labelMenuEntrySwapperChoices(root);
        }

        // Optional presentation filter: remove only Jagex's existing Last-destination entry
        // from the current Fairy Ring menu tree. This is a static user-configured Fairy Ring
        // menu preference; it does not depend on NPC/player/combat state, clear the remembered
        // destination, or create/invoke/replace a teleport action.
        if (config.hideRecentDestination())
        {
            hideLastDestinationEntries(root);
        }

        // Hide only the dedicated top-level Zanaris shortcut as a static user-configured Fairy
        // Ring menu preference. A BKS entry inside the user's Favourites submenu is untouched.
        if (config.hideZanaris())
        {
            hideTopLevelZanarisEntries(root);
        }

        for (MenuEntry entry : root.getMenuEntries())
        {
            String target = Text.removeTags(nullToEmpty(entry.getTarget())).toLowerCase(Locale.ROOT);
            if (!target.contains("fairy ring"))
            {
                continue;
            }

            // Walk the complete existing menu tree. Menu Entry Swapper and Fairy Ring
            // Favourites can nest the native Favourites destinations more than one level
            // below the Fairy Ring root, so a one-level pass can miss the actual DKR/AIQ
            // entries after another plugin has already relabelled them.
            processEntryTree(entry, false, currentRecentCode);
        }

    }

    /**
     * Applies the saved quick destination for the physical ring currently under the mouse.
     *
     * MenuEntry objects are owned by the Menu that created them, so a Favourites submenu entry
     * cannot be inserted directly into the root menu. Reuse the existing root-native action slot
     * instead, copying the selected Favorite's action metadata into that root-owned entry.
     *
     * When Configure is the current root action, preserve a root-owned copy immediately below the
     * reused slot first. This keeps Configure available on right-click without synthesizing a new
     * teleport action or re-parenting a submenu-owned MenuEntry.
     *
     * If the saved code is no longer favorited, the menu is left unchanged.
     */
    private void applyPerRingQuickDestination(Menu root)
    {
        String ringKey = findCurrentRingKey(root);
        String desiredCode = quickDestinationService.get(ringKey);
        if (desiredCode == null)
        {
            return;
        }

        Menu favoritesMenu = findFavoritesMenu(root);
        if (favoritesMenu == null)
        {
            return;
        }

        MenuEntry desiredEntry = findCodeEntry(favoritesMenu, desiredCode);
        if (desiredEntry == null)
        {
            return;
        }

        MenuEntry defaultAction = findDefaultFairyRingActionEntry(root);
        if (defaultAction == null)
        {
            return;
        }

        // If the desired Favorite is already a direct root action (for example because it is
        // also RuneLite's global MES default), there is nothing to apply.
        for (MenuEntry entry : root.getMenuEntries())
        {
            if (entry.getSubMenu() != null || !isFairyRingEntry(entry))
            {
                continue;
            }

            String option = Text.removeTags(nullToEmpty(entry.getOption())).trim();
            if (option.regionMatches(true, 0, "Last", 0, 4))
            {
                continue;
            }

            if (desiredCode.equals(resolveCode(entry)))
            {
                return;
            }
        }

        String currentLabel = Text.removeTags(nullToEmpty(defaultAction.getOption())).trim();

        // A submenu-owned MenuEntry cannot be appended directly to the root menu. RuneLite
        // correctly rejects that because desiredEntry belongs to the Favourites submenu. Instead,
        // preserve Configure with a new ROOT-owned non-teleport entry, inserted immediately below
        // the existing action slot, then safely reuse the original root-owned slot for the Favorite.
        if (currentLabel.equalsIgnoreCase("Configure"))
        {
            MenuEntry[] rootEntries = root.getMenuEntries();
            int defaultIndex = identityIndexOf(rootEntries, defaultAction);
            if (defaultIndex >= 0)
            {
                MenuEntry preservedConfigure = root.createMenuEntry(defaultIndex);
                copyAction(defaultAction, preservedConfigure);
            }
        }

        copyAction(desiredEntry, defaultAction);
        rememberCode(defaultAction, desiredCode);

    }

    private static int identityIndexOf(MenuEntry[] entries, MenuEntry target)
    {
        for (int i = 0; i < entries.length; i++)
        {
            if (entries[i] == target)
            {
                return i;
            }
        }
        return -1;
    }

    /**
     * Copies an already-existing MenuEntry action into another entry owned by the current menu.
     * The callback is copied by reference and is not executed here; Organizer does not synthesize
     * a new server action or call the copied Favorite action programmatically.
     */
    private static void copyAction(MenuEntry source, MenuEntry target)
    {
        target
            .setOption(source.getOption())
            .setTarget(source.getTarget())
            .setIdentifier(source.getIdentifier())
            .setType(source.getType())
            .setParam0(source.getParam0())
            .setParam1(source.getParam1())
            .setWorldViewId(source.getWorldViewId())
            .setForceLeftClick(source.isForceLeftClick())
            .setDeprioritized(source.isDeprioritized())
            .onClick(source.onClick());
    }

    private String findCurrentRingKey(Menu root)
    {
        MenuEntry entry = findCurrentPhysicalRingEntry(root);
        return quickDestinationService.keyForMenuEntry(entry);
    }

    /**
     * Return a native entry for the physical Fairy Ring currently under the mouse.
     * Prefer Examine because RuneLite uses it as the stable object anchor for custom
     * object swaps; fall back to native action entries when Examine is unavailable.
     */
    MenuEntry findCurrentPhysicalRingEntry(Menu root)
    {
        if (root == null)
        {
            return null;
        }

        // EXAMINE_OBJECT is the most reliable physical-object anchor. RuneLite's own
        // object customization code uses the Examine entry to resolve the object under
        // the mouse, and its scene coordinates are not affected by a Favorite sub-op
        // being promoted to left-click.
        for (MenuEntry entry : root.getMenuEntries())
        {
            if (isFairyRingEntry(entry) && entry.getType() == MenuAction.EXAMINE_OBJECT)
            {
                return entry;
            }
        }

        MenuEntry fallback = null;
        for (MenuEntry entry : root.getMenuEntries())
        {
            if (!isFairyRingEntry(entry) || entry.getType() == null)
            {
                continue;
            }

            switch (entry.getType())
            {
                case GAME_OBJECT_FIRST_OPTION:
                case GAME_OBJECT_SECOND_OPTION:
                case GAME_OBJECT_THIRD_OPTION:
                case GAME_OBJECT_FOURTH_OPTION:
                case GAME_OBJECT_FIFTH_OPTION:
                    if (fallback == null)
                    {
                        fallback = entry;
                    }
                    String option = Text.removeTags(nullToEmpty(entry.getOption())).trim();
                    if (option.equalsIgnoreCase("Configure"))
                    {
                        return entry;
                    }
                    break;
                default:
                    break;
            }
        }
        return fallback;
    }

    String resolveMenuCode(MenuEntry entry)
    {
        return resolveCode(entry);
    }

    List<String> getFavoriteCodesSnapshot()
    {
        return new ArrayList<>(favoriteCodesSnapshot);
    }

    private void snapshotFavoriteCodes(Menu root)
    {
        Menu favoritesMenu = findFavoritesMenu(root);
        if (favoritesMenu == null)
        {
            favoriteCodesSnapshot = new ArrayList<>();
            return;
        }

        Set<String> codes = new LinkedHashSet<>();
        collectCodes(favoritesMenu, codes);
        favoriteCodesSnapshot = orderService.sortCodes(
            new ArrayList<>(codes), FairyRingSection.FAVORITES, config.favoriteSort());
    }

    private Menu findFavoritesMenu(Menu menu)
    {
        if (menu == null)
        {
            return null;
        }

        // There can be more than one entry named Favourites in the Fairy Ring menu tree.
        // In particular, Menu Entry Swapper can create a helper/configuration Favourites
        // entry in addition to Jagex's real action-bearing Favourites submenu. Returning
        // the first match can therefore select an empty/helper submenu and make the
        // per-ring feature believe there are no Favorites even while the real submenu is
        // visible and populated. Choose the Favourites branch containing the most
        // recognized fairy-ring destination codes instead.
        List<Menu> candidates = new ArrayList<>();
        collectFavoritesMenus(menu, candidates);

        Menu best = null;
        int bestCodeCount = 0;
        for (Menu candidate : candidates)
        {
            Set<String> codes = new LinkedHashSet<>();
            collectCodes(candidate, codes);
            if (codes.size() > bestCodeCount)
            {
                best = candidate;
                bestCodeCount = codes.size();
            }
        }

        return best;
    }

    private void collectFavoritesMenus(Menu menu, List<Menu> result)
    {
        if (menu == null)
        {
            return;
        }

        for (MenuEntry entry : menu.getMenuEntries())
        {
            Menu submenu = entry.getSubMenu();
            if (submenu == null)
            {
                continue;
            }

            if (isFavoritesParent(entry))
            {
                result.add(submenu);
            }

            collectFavoritesMenus(submenu, result);
        }
    }

    private MenuEntry findCodeEntry(Menu menu, String code)
    {
        if (menu == null)
        {
            return null;
        }

        for (MenuEntry entry : menu.getMenuEntries())
        {
            if (code.equals(resolveCode(entry)))
            {
                return entry;
            }

            Menu submenu = entry.getSubMenu();
            if (submenu != null)
            {
                MenuEntry nested = findCodeEntry(submenu, code);
                if (nested != null)
                {
                    return nested;
                }
            }
        }
        return null;
    }

    private void collectCodes(Menu menu, Set<String> result)
    {
        if (menu == null)
        {
            return;
        }

        for (MenuEntry entry : menu.getMenuEntries())
        {
            String code = resolveCode(entry);
            if (code != null)
            {
                result.add(code);
            }

            Menu submenu = entry.getSubMenu();
            if (submenu != null)
            {
                collectCodes(submenu, result);
            }
        }
    }

    /**
     * Find the action-bearing Fairy Ring entry RuneLite currently treats as the default
     * left-click. RuneLite menu arrays are ordered bottom-to-top for display/default
     * priority, so scan from the end and take the first native object action for this ring.
     * RUNELITE helper entries, submenus, Walk here, and Examine are intentionally skipped.
     */
    private MenuEntry findDefaultFairyRingActionEntry(Menu root)
    {
        MenuEntry[] entries = root.getMenuEntries();
        for (int i = entries.length - 1; i >= 0; i--)
        {
            MenuEntry entry = entries[i];
            if (!isFairyRingEntry(entry) || entry.getSubMenu() != null || entry.getType() == null)
            {
                continue;
            }

            switch (entry.getType())
            {
                case GAME_OBJECT_FIRST_OPTION:
                case GAME_OBJECT_SECOND_OPTION:
                case GAME_OBJECT_THIRD_OPTION:
                case GAME_OBJECT_FOURTH_OPTION:
                case GAME_OBJECT_FIFTH_OPTION:
                    return entry;
                default:
                    break;
            }
        }
        return null;
    }

    /**
     * Applies Organizer presentation recursively to the existing Fairy Ring menu tree.
     * Nothing is created or invoked here; the same MenuEntry objects are only relabelled,
     * optionally reordered inside a Favourites submenu, and cosmetically colored.
     */
    private void processEntryTree(MenuEntry entry, boolean insideFavorites, String currentRecentCode)
    {
        if (entry == null)
        {
            return;
        }

        if (config.labelMenus())
        {
            labelExistingEntry(entry);
        }

        // A destination below a Favourites parent is a favorite even when MES inserts an
        // intermediate submenu layer. Carry that context down the complete descendant tree.
        if (insideFavorites)
        {
            colorFavoriteEntry(entry);
        }

        Menu submenu = entry.getSubMenu();
        if (submenu == null)
        {
            return;
        }

        boolean favoritesParent = isFavoritesParent(entry);
        boolean favoritesBranch = insideFavorites || favoritesParent;

        // Hide recent applies to both representations of the same destination: the top-level
        // Last shortcut and, when present, its duplicate inside the user's Favourites submenu.
        // This does not unfavorite it, alter saved manual order, or touch Jagex's remembered
        // destination. Filtering is recursive so MES-created wrapper menus are handled without
        // flattening or recreating any action-bearing entry.
        if (favoritesParent && config.hideRecentDestination() && currentRecentCode != null)
        {
            hideDestinationCodeEntries(submenu, currentRecentCode);
        }

        MenuEntry[] children = submenu.getMenuEntries();

        // Reorder only the existing entries belonging to the actual Favourites submenu.
        // Nested wrapper menus are traversed but never flattened or recreated.
        if (config.reorderFavoriteSubmenu() && favoritesParent)
        {
            children = reorderExistingFavoriteEntries(children);
            submenu.setMenuEntries(children);
        }

        for (MenuEntry child : children)
        {
            processEntryTree(child, favoritesBranch, currentRecentCode);
        }
    }

    /**
     * Relabels only the choices inside RuneLite Menu Entry Swapper's object-swap helper
     * submenus for a Fairy Ring. The helper entries are RUNELITE configuration callbacks,
     * not teleport actions; changing their displayed option leaves the callback untouched.
     */
    public void refreshMenuEntrySwapperLabels()
    {
        if (!config.labelMenus() || !client.isMenuOpen() || !rootContainsFairyRing())
        {
            return;
        }

        // A tick-end retry covers clients/plugins that finish attaching their helper
        // submenus after the MenuOpened subscriber chain has begun.
        captureCodes();
        labelMenuEntrySwapperChoices(client.getMenu());
    }

    private void labelMenuEntrySwapperChoices(Menu root)
    {
        for (MenuEntry entry : root.getMenuEntries())
        {
            if (!isFairyRingSwapMenu(entry))
            {
                continue;
            }

            Menu submenu = entry.getSubMenu();
            if (submenu == null)
            {
                continue;
            }

            for (MenuEntry child : submenu.getMenuEntries())
            {
                labelMenuEntrySwapperChoiceTree(child);
            }
        }
    }

    private void labelMenuEntrySwapperChoiceTree(MenuEntry entry)
    {
        if (entry == null)
        {
            return;
        }

        String code = resolveCode(entry);
        if (code != null)
        {
            labelExistingEntry(entry);
        }

        Menu submenu = entry.getSubMenu();
        if (submenu != null)
        {
            for (MenuEntry child : submenu.getMenuEntries())
            {
                labelMenuEntrySwapperChoiceTree(child);
            }
        }
    }

    private static boolean isFairyRingSwapMenu(MenuEntry entry)
    {
        if (!isFairyRingEntry(entry))
        {
            return false;
        }

        String option = Text.removeTags(nullToEmpty(entry.getOption())).trim();
        return option.equalsIgnoreCase("Swap left-click")
            || option.equalsIgnoreCase("Swap shift-click");
    }

    public void clearIdentityCache()
    {
        menuEntryCodes.clear();
        recentDestinationCode = null;
        fairyMenuSeen = false;
        captureActive = false;
        favoriteCodesSnapshot = new ArrayList<>();
    }

    private void captureEntryTree(MenuEntry entry)
    {
        String code = resolveCode(entry);
        if (code != null && isLastDestinationOption(entry))
        {
            recentDestinationCode = code;
        }

        Menu submenu = entry.getSubMenu();
        if (submenu == null)
        {
            return;
        }
        for (MenuEntry child : submenu.getMenuEntries())
        {
            captureEntryTree(child);
        }
    }

    /**
     * Finds the code carried by Jagex's current Last-destination entry before any optional
     * Organizer filtering removes it from the visible menu.
     */
    private String findLastDestinationCode(Menu menu)
    {
        for (MenuEntry entry : menu.getMenuEntries())
        {
            if (isLastDestinationOption(entry))
            {
                String code = resolveCode(entry);
                if (code != null)
                {
                    return code;
                }
            }

            Menu submenu = entry.getSubMenu();
            if (submenu != null)
            {
                String nested = findLastDestinationCode(submenu);
                if (nested != null)
                {
                    return nested;
                }
            }
        }
        return null;
    }

    private boolean isLastDestinationOption(MenuEntry entry)
    {
        if (!isFairyRingEntry(entry))
        {
            return false;
        }

        String option = Text.removeTags(nullToEmpty(entry.getOption())).trim();
        return LAST_DESTINATION.matcher(option).matches()
            || option.regionMatches(true, 0, "Last:", 0, 5);
    }

    /** Remove only root-level BKS/Zanaris presentation; nested favorite BKS entries are untouched. */
    private void hideTopLevelZanarisEntries(Menu root)
    {
        MenuEntry[] entries = root.getMenuEntries();
        if (entries.length == 0)
        {
            return;
        }

        List<MenuEntry> kept = new ArrayList<>(entries.length);
        boolean changed = false;
        for (MenuEntry entry : entries)
        {
            if (isFairyRingEntry(entry)
                && !isLastDestinationOption(entry)
                && "BKS".equals(resolveCode(entry)))
            {
                changed = true;
                continue;
            }
            kept.add(entry);
        }

        if (changed)
        {
            root.setMenuEntries(kept.toArray(new MenuEntry[0]));
        }
    }

    /**
     * Removes a matching destination from an existing submenu tree without changing the
     * action-bearing MenuEntry objects that remain. Used only for presentation filtering.
     */
    private void hideDestinationCodeEntries(Menu menu, String codeToHide)
    {
        String normalized = FairyRingOrderService.normalizeCode(codeToHide);
        if (!FairyRingDestination.isValidCode(normalized))
        {
            return;
        }

        MenuEntry[] entries = menu.getMenuEntries();
        if (entries.length == 0)
        {
            return;
        }

        List<MenuEntry> kept = new ArrayList<>(entries.length);
        boolean changed = false;
        for (MenuEntry entry : entries)
        {
            Menu submenu = entry.getSubMenu();
            if (submenu != null)
            {
                hideDestinationCodeEntries(submenu, normalized);
            }

            if (normalized.equals(resolveCode(entry)))
            {
                changed = true;
                continue;
            }

            kept.add(entry);
        }

        if (changed)
        {
            menu.setMenuEntries(kept.toArray(new MenuEntry[0]));
        }
    }

    private MenuEntry[] reorderExistingFavoriteEntries(MenuEntry[] entries)
    {
        List<MenuEntry> codeEntries = new ArrayList<>();
        Map<MenuEntry, String> codes = new HashMap<>();

        for (MenuEntry entry : entries)
        {
            String code = resolveCode(entry);
            if (code != null)
            {
                codeEntries.add(entry);
                codes.put(entry, code);
            }
        }

        if (codeEntries.size() < 2)
        {
            return entries;
        }

        List<String> currentInternalCodes = codeEntries.stream().map(codes::get).collect(Collectors.toList());
        List<String> desiredVisibleCodes = orderService.sortCodes(
            currentInternalCodes,
            FairyRingSection.FAVORITES,
            config.favoriteSort());

        // RuneLite stores menu entries in the inverse of their top-to-bottom visual order:
        // the last entry in the MenuEntry[] is drawn at the top of the submenu. Therefore
        // the existing entry array must be arranged bottom-to-top so the rendered submenu
        // mirrors the Favorites order shown in Configure.
        List<String> desiredInternalCodes = new ArrayList<>(desiredVisibleCodes);
        Collections.reverse(desiredInternalCodes);

        Map<String, Integer> rank = new HashMap<>();
        for (int index = 0; index < desiredInternalCodes.size(); index++)
        {
            rank.put(desiredInternalCodes.get(index), index);
        }

        codeEntries.sort(Comparator.comparingInt(entry -> rank.getOrDefault(codes.get(entry), Integer.MAX_VALUE)));

        // Preserve every non-code entry and its slot. Only replace slots occupied by
        // recognized fairy-ring codes with the same existing entries in a different order.
        MenuEntry[] result = entries.clone();
        int replacement = 0;
        for (int index = 0; index < result.length; index++)
        {
            if (resolveCode(result[index]) != null)
            {
                result[index] = codeEntries.get(replacement++);
            }
        }
        return result;
    }

    /**
     * Removes native Last-destination entries from the currently relevant fairy-ring menu
     * tree. The underlying Jagex destination state is untouched; only the current local
     * menu presentation is filtered.
     */
    private void hideLastDestinationEntries(Menu menu)
    {
        MenuEntry[] entries = menu.getMenuEntries();
        if (entries.length == 0)
        {
            return;
        }

        List<MenuEntry> kept = new ArrayList<>(entries.length);
        boolean changed = false;

        for (MenuEntry entry : entries)
        {
            Menu submenu = entry.getSubMenu();
            if (submenu != null)
            {
                hideLastDestinationEntries(submenu);
            }

            if (isLastDestinationEntry(entry))
            {
                changed = true;
                continue;
            }

            kept.add(entry);
        }

        if (changed)
        {
            menu.setMenuEntries(kept.toArray(new MenuEntry[0]));
        }
    }

    private boolean isLastDestinationEntry(MenuEntry entry)
    {
        if (!isFairyRingEntry(entry))
        {
            return false;
        }

        String option = Text.removeTags(nullToEmpty(entry.getOption())).trim();
        if (LAST_DESTINATION.matcher(option).matches())
        {
            return true;
        }

        // A second presentation pass can see the Organizer's own reformatted Last: label.
        // Require a cached/parseable fairy-ring code so unrelated entries beginning with
        // "Last:" are never removed.
        return option.regionMatches(true, 0, "Last:", 0, 5) && resolveCode(entry) != null;
    }

    private void labelExistingEntry(MenuEntry entry)
    {
        String option = Text.removeTags(nullToEmpty(entry.getOption())).trim();

        Matcher originalLast = LAST_DESTINATION.matcher(option);
        if (originalLast.matches())
        {
            String code = originalLast.group(1);
            rememberCode(entry, code);
            setLastDestinationLabel(entry, code);
            return;
        }

        // If this Organizer pass has already changed Last-destination to "Last: GE",
        // the identity cache still tells us which code this existing MenuEntry represents.
        if (option.regionMatches(true, 0, "Last:", 0, 5))
        {
            String code = resolveCode(entry);
            if (code != null)
            {
                setLastDestinationLabel(entry, code);
            }
            return;
        }

        String code = resolveCode(entry);
        if (code == null)
        {
            return;
        }

        String label = labelService.getEffectiveName(code);
        String newOption = config.showCodeInMenuLabel() ? label + " (" + code + ')' : label;
        entry.setOption(newOption);
    }

    private void colorFavoriteEntry(MenuEntry entry)
    {
        String code = resolveCode(entry);
        if (code == null)
        {
            return;
        }

        Color color = colorService.getFavoriteMenuColor(code);
        if (color == null)
        {
            return;
        }

        String plainOption = Text.removeTags(nullToEmpty(entry.getOption()));
        entry.setOption(ColorUtil.prependColorTag(plainOption, color));
    }

    private void setLastDestinationLabel(MenuEntry entry, String code)
    {
        String label = labelService.getEffectiveName(code);
        entry.setOption(config.showCodeInMenuLabel()
            ? "Last: " + label + " (" + code + ')'
            : "Last: " + label);
    }

    private static boolean isFairyRingEntry(MenuEntry entry)
    {
        return entry != null && isFairyRingTarget(entry.getTarget());
    }

    private static boolean isFairyRingTarget(String target)
    {
        if (target == null)
        {
            return false;
        }

        // MenuEntryAdded is a hot path. Tags do not split the visible words, so avoid
        // allocating a tag-stripped/lower-cased copy just to identify the target.
        final String needle = "fairy ring";
        for (int index = 0; index <= target.length() - needle.length(); index++)
        {
            if (target.regionMatches(true, index, needle, 0, needle.length()))
            {
                return true;
            }
        }
        return false;
    }

    private static boolean isFavoritesParent(MenuEntry entry)
    {
        String option = Text.removeTags(nullToEmpty(entry.getOption())).trim();
        return option.equalsIgnoreCase("Favourites") || option.equalsIgnoreCase("Favorites");
    }

    private String resolveCode(MenuEntry entry)
    {
        String cached = menuEntryCodes.get(entry);
        if (cached != null)
        {
            return cached;
        }

        String parsed = extractCode(entry.getOption());
        if (parsed == null)
        {
            // Compatibility with Fairy Ring Favourites and similar presentation plugins:
            // if they have already converted a bare code to a destination name (and possibly
            // hidden the code), map that known alias back to the original MenuEntry identity.
            parsed = labelService.resolveCodeFromDisplayLabel(entry.getOption());
        }
        if (parsed != null)
        {
            rememberCode(entry, parsed);
        }
        return parsed;
    }

    private void rememberCode(MenuEntry entry, String code)
    {
        String normalized = FairyRingOrderService.normalizeCode(code);
        if (entry != null && FairyRingDestination.isValidCode(normalized))
        {
            menuEntryCodes.put(entry, normalized);
        }
    }

    /** Supports both Jagex bare codes and the Organizer's own Name (CODE) display format. */
    private static String extractCode(String option)
    {
        String plain = Text.removeTags(nullToEmpty(option)).trim().toUpperCase(Locale.ROOT);
        Matcher bare = BARE_CODE.matcher(plain);
        if (bare.matches())
        {
            return bare.group(1);
        }

        Matcher parens = CODE_IN_PARENS.matcher(plain);
        if (parens.matches())
        {
            return parens.group(1);
        }
        return null;
    }

    private static String nullToEmpty(String value)
    {
        return value == null ? "" : value;
    }
}

package com.fairyringorganizer;

import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Singleton;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;

/**
 * Tracks only the Fairy Ring Travel Log row widgets handed to it by FairyRingWidgetScanner.
 * Capturing the native presentation before edits lets disabling the plugin restore the already-
 * open Configure interface without deleting saved Organizer preferences. No game-world, dial,
 * confirm-button, inventory, combat, equipment, prayer, or spellbook geometry is stored/changed.
 *
 * The service also remembers the last values applied by this plugin. If Jagex later changes
 * a still-live widget (for example after favorite membership changes), the new value is
 * recognized as external/native state and replaces the older snapshot instead of being
 * mistaken for another Organizer edit.
 */
@Singleton
public class FairyRingNativeStateService
{
    private final Map<FairyRingSection, SectionSnapshot> snapshots = new EnumMap<>(FairyRingSection.class);

    // Keep one untouched Jagex label template per code for the lifetime of the open Fairy Ring
    // interface. Search deliberately clears/rebuilds the section snapshots, but a custom label
    // must still be able to Reset immediately after that rebuild instead of waiting for the
    // entire interface to be closed and reconstructed.
    private final Map<String, NativeLabelTemplate> nativeLabelsByCode = new HashMap<>();

    public void capture(FairyRingSection section, Widget container, List<FairyRingRow> rows)
    {
        if (container == null || rows == null)
        {
            return;
        }

        SectionSnapshot snapshot = snapshots.get(section);
        if (snapshot == null || snapshot.container != container)
        {
            snapshot = new SectionSnapshot(container);
            snapshots.put(section, snapshot);
        }

        for (FairyRingRow row : rows)
        {
            for (Widget widget : row.getMemberWidgets())
            {
                removeWidgetFromOtherSections(section, widget);
                snapshot.touchedWidgets.add(widget);
                int currentY = widget.getOriginalY();
                Integer lastApplied = snapshot.lastAppliedY.get(widget);
                if (!snapshot.originalY.containsKey(widget)
                    || (lastApplied != null && currentY != lastApplied))
                {
                    snapshot.originalY.put(widget, currentY);
                }

                // Custom names can change the number of rendered text lines. Capture every
                // text member's untouched Jagex height once so a later refresh/search/disable
                // can return the row to native geometry before applying the current custom name.
                if (widget.getType() == WidgetType.TEXT)
                {
                    snapshot.originalTextHeightInput.putIfAbsent(widget, widget.getOriginalHeight());
                    snapshot.originalTextHeightMode.putIfAbsent(widget, widget.getHeightMode());
                }
            }

            Widget labelWidget = row.getLabelWidget();
            if (labelWidget != null)
            {
                removeLabelFromOtherSections(section, labelWidget);

                // Capture the untouched Jagex template by code before Organizer substitutes a
                // custom name. This code-level template intentionally survives search/layout
                // snapshot clears so Reset can restore a newly rebuilt Widget immediately.
                nativeLabelsByCode.putIfAbsent(row.getCode(), new NativeLabelTemplate(
                    labelWidget.getText(),
                    labelWidget.getOriginalHeight(),
                    labelWidget.getHeightMode(),
                    labelWidget.getYTextAlignment(),
                    Math.max(1, labelWidget.getHeight())));

                // Keep the widget-local snapshot as well for native-state restoration on disable.
                if (!snapshot.originalLabel.containsKey(labelWidget))
                {
                    snapshot.originalLabel.put(labelWidget, labelWidget.getText());
                    snapshot.originalLabelHeightInput.put(labelWidget, labelWidget.getOriginalHeight());
                    snapshot.originalLabelHeightMode.put(labelWidget, labelWidget.getHeightMode());
                    snapshot.originalLabelRenderedHeight.put(labelWidget, Math.max(1, labelWidget.getHeight()));
                    snapshot.originalLabelYTextAlignment.put(labelWidget, labelWidget.getYTextAlignment());
                }
            }
        }
    }

    /** Restore one row label to the untouched Jagex value captured for this code. */
    public void restoreLabel(FairyRingSection section, String code, Widget labelWidget)
    {
        if (labelWidget == null)
        {
            return;
        }

        NativeLabelTemplate template = nativeLabelsByCode.get(FairyRingOrderService.normalizeCode(code));
        if (template != null)
        {
            restoreTemplate(labelWidget, template);
            return;
        }

        // Fallback for a code first encountered before a code-level template was available.
        SectionSnapshot snapshot = snapshots.get(section);
        if (snapshot != null && snapshot.originalLabel.containsKey(labelWidget))
        {
            Integer heightMode = snapshot.originalLabelHeightMode.get(labelWidget);
            Integer heightInput = snapshot.originalLabelHeightInput.get(labelWidget);
            Integer yTextAlignment = snapshot.originalLabelYTextAlignment.get(labelWidget);
            if (heightMode != null)
            {
                labelWidget.setHeightMode(heightMode);
            }
            if (heightInput != null)
            {
                labelWidget.setOriginalHeight(heightInput);
            }
            if (yTextAlignment != null)
            {
                labelWidget.setYTextAlignment(yTextAlignment);
            }
            labelWidget.setText(snapshot.originalLabel.get(labelWidget));
            labelWidget.revalidate();
        }
    }

    /**
     * Apply one calculated rendered height to both text widgets that make up a Fairy Ring row
     * (the three-letter code and destination label). Jagex gives those widgets the same height;
     * keeping them synchronized preserves the clickbox while allowing a short custom label to
     * collapse a formerly multi-line native row.
     */
    public void applyDynamicRowTextHeight(FairyRingSection section, FairyRingRow row, int renderedHeight)
    {
        if (row == null || renderedHeight <= 0)
        {
            return;
        }

        SectionSnapshot snapshot = snapshots.get(section);
        for (Widget widget : row.getMemberWidgets())
        {
            if (widget == null || widget.getType() != WidgetType.TEXT)
            {
                continue;
            }

            int nativeMode = snapshot == null
                ? widget.getHeightMode()
                : snapshot.originalTextHeightMode.getOrDefault(widget, widget.getHeightMode());
            widget.setHeightMode(nativeMode);
            widget.setOriginalHeight(renderedHeight);
            widget.revalidate();
        }
    }

    /** Restore both row text widgets to the untouched Jagex height captured for this interface. */
    public void restoreRowTextHeight(FairyRingSection section, FairyRingRow row)
    {
        if (row == null)
        {
            return;
        }

        SectionSnapshot snapshot = snapshots.get(section);
        NativeLabelTemplate template = nativeLabelsByCode.get(FairyRingOrderService.normalizeCode(row.getCode()));

        for (Widget widget : row.getMemberWidgets())
        {
            if (widget == null || widget.getType() != WidgetType.TEXT)
            {
                continue;
            }

            Integer mode = snapshot == null ? null : snapshot.originalTextHeightMode.get(widget);
            Integer input = snapshot == null ? null : snapshot.originalTextHeightInput.get(widget);

            // Active search intentionally clears the widget-level section snapshots. The
            // code-level native label template survives that handoff, and Fairy Ring rows use
            // the same native text height for both the code and destination widgets. Use that
            // template as the reset fallback so a custom label changed during search cannot
            // leave the row stuck at its old expanded/contracted height.
            if (mode == null && template != null)
            {
                mode = template.heightMode;
            }
            if (input == null && template != null)
            {
                input = template.heightInput;
            }

            if (mode != null)
            {
                widget.setHeightMode(mode);
            }
            if (input != null)
            {
                widget.setOriginalHeight(input);
            }
            widget.revalidate();
        }
    }

    /**
     * Replace only the visible destination text while preserving Jagex's own row markup and
     * automatic text sizing. The native destination text contains layout markup which reserves
     * the first line for the three-letter code. Replacing the raw text with plain custom text
     * stripped that layout marker in earlier test builds, which is why short labels overlapped
     * the code.
     *
     * Restore the native sizing inputs before replacing the text. The controller then measures
     * the replacement and synchronizes both row text widgets to the required rendered height.
     */
    public void applyLabelPreservingNativeLayout(
        FairyRingSection section, String code, Widget labelWidget, String text)
    {
        if (labelWidget == null || text == null)
        {
            return;
        }

        NativeLabelTemplate template = nativeLabelsByCode.get(FairyRingOrderService.normalizeCode(code));
        if (template == null)
        {
            SectionSnapshot snapshot = snapshots.get(section);
            if (snapshot != null && snapshot.originalLabel.containsKey(labelWidget))
            {
                template = new NativeLabelTemplate(
                    snapshot.originalLabel.get(labelWidget),
                    snapshot.originalLabelHeightInput.getOrDefault(labelWidget, labelWidget.getOriginalHeight()),
                    snapshot.originalLabelHeightMode.getOrDefault(labelWidget, labelWidget.getHeightMode()),
                    snapshot.originalLabelYTextAlignment.getOrDefault(labelWidget, labelWidget.getYTextAlignment()),
                    snapshot.originalLabelRenderedHeight.getOrDefault(
                        labelWidget, Math.max(1, labelWidget.getHeight())));
            }
        }

        if (template == null)
        {
            // Last-resort fallback: still reserve the native code line.
            labelWidget.setText("<br>" + text);
            labelWidget.revalidate();
            return;
        }

        // Restore the native auto-sizing inputs first. The custom label then gets the same
        // dynamic wrapping behavior as a normal Jagex destination instead of an absolute height.
        labelWidget.setHeightMode(template.heightMode);
        labelWidget.setOriginalHeight(template.heightInput);
        labelWidget.setYTextAlignment(template.yTextAlignment);
        labelWidget.setText(nativeLinePrefix(template.rawText) + text);
        labelWidget.revalidate();
    }

    private static void restoreTemplate(Widget widget, NativeLabelTemplate template)
    {
        widget.setHeightMode(template.heightMode);
        widget.setOriginalHeight(template.heightInput);
        widget.setYTextAlignment(template.yTextAlignment);
        widget.setText(template.rawText);
        widget.revalidate();
    }

    /**
     * Preserve only the leading native line-break layout tags. Other style tags are intentionally
     * left to the Widget's native color/font properties so an opening formatting tag can never be
     * copied without its matching closing tag. If the client ever omits the line break entirely,
     * add one so the custom destination can never occupy the code line.
     */
    private static String nativeLinePrefix(String rawText)
    {
        if (rawText == null || rawText.isEmpty())
        {
            return "<br>";
        }

        int index = 0;
        int breaks = 0;
        while (index < rawText.length())
        {
            char ch = rawText.charAt(index);
            if (Character.isWhitespace(ch))
            {
                index++;
                continue;
            }
            if (ch != '<')
            {
                break;
            }

            int close = rawText.indexOf('>', index + 1);
            if (close < 0)
            {
                break;
            }

            String tag = rawText.substring(index + 1, close).trim();
            if ("br".equalsIgnoreCase(tag))
            {
                breaks++;
            }
            index = close + 1;
        }

        if (breaks <= 0)
        {
            breaks = 1;
        }

        StringBuilder prefix = new StringBuilder(breaks * 4);
        for (int i = 0; i < breaks; i++)
        {
            prefix.append("<br>");
        }
        return prefix.toString();
    }

    /**
     * Native rendered destination height captured before Organizer replaces the text.
     * This survives search snapshot clears so dynamic custom-name packing can always return
     * a row to its real Jagex baseline instead of treating a previously-expanded Organizer
     * gap as the new native size.
     */
    public int getNativeLabelRenderedHeight(String code)
    {
        NativeLabelTemplate template = nativeLabelsByCode.get(FairyRingOrderService.normalizeCode(code));
        return template == null ? -1 : template.renderedHeight;
    }

    /** Call after the Organizer has finished moving/relabeling a section. */
    public void recordApplied(FairyRingSection section, List<FairyRingRow> rows)
    {
        SectionSnapshot snapshot = snapshots.get(section);
        if (snapshot == null || rows == null)
        {
            return;
        }

        for (FairyRingRow row : rows)
        {
            for (Widget widget : row.getMemberWidgets())
            {
                snapshot.lastAppliedY.put(widget, widget.getOriginalY());
            }

            Widget labelWidget = row.getLabelWidget();
            if (labelWidget != null)
            {
                snapshot.lastAppliedLabel.put(labelWidget, labelWidget.getText());
            }
        }
    }

    /**
     * Clears only Organizer forced coordinates from still-live widgets. Native originalY values
     * and captured labels remain untouched, so the same refresh can immediately rescan and
     * apply a different sort without carrying geometry from the previous mode.
     */
    public void clearForcedPositions()
    {
        // Clearing a forced position only removes the override; the widget can continue to
        // expose the sentinel relative coordinates (-1, -1) until its layout is recomputed.
        // That is particularly visible when the Fairy Ring search immediately starts hiding
        // and compacting rows. Clear every override first, then revalidate the affected widgets
        // and section containers before Jagex's filter layout is allowed to render.
        Set<Widget> touched = Collections.newSetFromMap(new IdentityHashMap<>());
        Set<Widget> containers = Collections.newSetFromMap(new IdentityHashMap<>());

        for (SectionSnapshot snapshot : snapshots.values())
        {
            if (snapshot.container != null)
            {
                containers.add(snapshot.container);
            }

            for (Widget widget : snapshot.touchedWidgets)
            {
                if (widget != null)
                {
                    touched.add(widget);
                }
            }
        }

        // Clear all Organizer overrides as one logical operation before recomputing any widget.
        // Also restore text-member heights here. Every normal refresh therefore starts from the
        // untouched native row geometry, and active search receives native sizing rather than a
        // custom-label expansion left over from the sorted presentation.
        for (SectionSnapshot snapshot : snapshots.values())
        {
            for (Widget widget : snapshot.touchedWidgets)
            {
                if (widget == null)
                {
                    continue;
                }
                widget.setForcedPosition(-1, -1);
                Integer mode = snapshot.originalTextHeightMode.get(widget);
                Integer input = snapshot.originalTextHeightInput.get(widget);
                if (mode != null)
                {
                    widget.setHeightMode(mode);
                }
                if (input != null)
                {
                    widget.setOriginalHeight(input);
                }
            }
        }

        // RuneLite's own widget-overlay restore path follows forced-position removal with a
        // revalidate so the native x/y/w/h are available immediately instead of on a later
        // client-script/layout pass.
        for (Widget widget : touched)
        {
            widget.revalidate();
        }

        for (Widget container : containers)
        {
            container.revalidateScroll();
        }
    }

    public void restoreAll()
    {
        for (SectionSnapshot snapshot : snapshots.values())
        {
            for (Map.Entry<Widget, Integer> entry : snapshot.originalY.entrySet())
            {
                Widget widget = entry.getKey();
                if (widget != null)
                {
                    widget.setForcedPosition(-1, -1);
                    widget.setOriginalY(entry.getValue());
                    Integer heightMode = snapshot.originalTextHeightMode.get(widget);
                    Integer heightInput = snapshot.originalTextHeightInput.get(widget);
                    if (heightMode != null)
                    {
                        widget.setHeightMode(heightMode);
                    }
                    if (heightInput != null)
                    {
                        widget.setOriginalHeight(heightInput);
                    }
                    widget.revalidate();
                }
            }

            for (Map.Entry<Widget, String> entry : snapshot.originalLabel.entrySet())
            {
                Widget widget = entry.getKey();
                if (widget != null)
                {
                    String code = FairyRingOrderService.normalizeCode(widget.getName());
                    NativeLabelTemplate template = nativeLabelsByCode.get(code);
                    if (template != null)
                    {
                        restoreTemplate(widget, template);
                    }
                    else
                    {
                        Integer heightMode = snapshot.originalLabelHeightMode.get(widget);
                        Integer heightInput = snapshot.originalLabelHeightInput.get(widget);
                        Integer yTextAlignment = snapshot.originalLabelYTextAlignment.get(widget);
                        if (heightMode != null)
                        {
                            widget.setHeightMode(heightMode);
                        }
                        if (heightInput != null)
                        {
                            widget.setOriginalHeight(heightInput);
                        }
                        if (yTextAlignment != null)
                        {
                            widget.setYTextAlignment(yTextAlignment);
                        }
                        widget.setText(entry.getValue());
                        widget.revalidate();
                    }
                }
            }

            for (Widget widget : snapshot.touchedWidgets)
            {
                if (widget != null)
                {
                    widget.setForcedPosition(-1, -1);
                }
            }

            if (snapshot.container != null)
            {
                snapshot.container.revalidateScroll();
            }
        }
        snapshots.clear();
        nativeLabelsByCode.clear();
    }

    public boolean hasLiveState()
    {
        return !snapshots.isEmpty();
    }

    /** Clear transient widget/layout snapshots but retain native label templates across search. */
    public void clear()
    {
        snapshots.clear();
    }

    /** Clear all live-interface state, including native label templates. */
    public void clearAll()
    {
        snapshots.clear();
        nativeLabelsByCode.clear();
    }

    private void removeWidgetFromOtherSections(FairyRingSection currentSection, Widget widget)
    {
        for (Map.Entry<FairyRingSection, SectionSnapshot> entry : snapshots.entrySet())
        {
            if (entry.getKey() == currentSection)
            {
                continue;
            }
            entry.getValue().originalY.remove(widget);
            entry.getValue().lastAppliedY.remove(widget);
            entry.getValue().originalTextHeightInput.remove(widget);
            entry.getValue().originalTextHeightMode.remove(widget);
        }
    }

    private void removeLabelFromOtherSections(FairyRingSection currentSection, Widget widget)
    {
        for (Map.Entry<FairyRingSection, SectionSnapshot> entry : snapshots.entrySet())
        {
            if (entry.getKey() == currentSection)
            {
                continue;
            }
            entry.getValue().originalLabel.remove(widget);
            entry.getValue().originalLabelHeightInput.remove(widget);
            entry.getValue().originalLabelHeightMode.remove(widget);
            entry.getValue().originalLabelRenderedHeight.remove(widget);
            entry.getValue().originalLabelYTextAlignment.remove(widget);
            entry.getValue().lastAppliedLabel.remove(widget);
        }
    }

    private static final class NativeLabelTemplate
    {
        private final String rawText;
        private final int heightInput;
        private final int heightMode;
        private final int yTextAlignment;
        private final int renderedHeight;

        private NativeLabelTemplate(
            String rawText, int heightInput, int heightMode, int yTextAlignment, int renderedHeight)
        {
            this.rawText = rawText == null ? "" : rawText;
            this.heightInput = heightInput;
            this.heightMode = heightMode;
            this.yTextAlignment = yTextAlignment;
            this.renderedHeight = Math.max(1, renderedHeight);
        }
    }

    private static final class SectionSnapshot
    {
        private final Widget container;
        private final Set<Widget> touchedWidgets = Collections.newSetFromMap(new IdentityHashMap<>());
        private final Map<Widget, Integer> originalY = new IdentityHashMap<>();
        private final Map<Widget, Integer> lastAppliedY = new IdentityHashMap<>();
        private final Map<Widget, Integer> originalTextHeightInput = new IdentityHashMap<>();
        private final Map<Widget, Integer> originalTextHeightMode = new IdentityHashMap<>();
        private final Map<Widget, String> originalLabel = new IdentityHashMap<>();
        private final Map<Widget, Integer> originalLabelHeightInput = new IdentityHashMap<>();
        private final Map<Widget, Integer> originalLabelHeightMode = new IdentityHashMap<>();
        private final Map<Widget, Integer> originalLabelRenderedHeight = new IdentityHashMap<>();
        private final Map<Widget, Integer> originalLabelYTextAlignment = new IdentityHashMap<>();
        private final Map<Widget, String> lastAppliedLabel = new IdentityHashMap<>();

        private SectionSnapshot(Widget container)
        {
            this.container = container;
        }
    }
}

package com.fairyringorganizer;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import java.util.stream.Collectors;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.Text;

/**
 * Computes display order and persists only fairy-ring code sequences through ConfigManager.
 * This service has no widget, menu, input, or game-action access.
 */
public class FairyRingOrderService
{
    private static final String FAVORITE_ORDER_KEY = "favoriteOrder";
    private static final String REMAINING_ORDER_KEY = "remainingOrder";

    private final ConfigManager configManager;
    private final FairyRingLabelService labelService;

    @Inject
    public FairyRingOrderService(ConfigManager configManager, FairyRingLabelService labelService)
    {
        this.configManager = configManager;
        this.labelService = labelService;
    }

    public List<String> sortCodes(List<String> visibleCodes, FairyRingSection section, SortMode mode)
    {
        List<String> normalized = visibleCodes.stream()
            .map(FairyRingOrderService::normalizeCode)
            .filter(FairyRingDestination::isValidCode)
            .distinct()
            .collect(Collectors.toCollection(ArrayList::new));

        if (mode == SortMode.CODE)
        {
            normalized.sort(String.CASE_INSENSITIVE_ORDER);
            return normalized;
        }

        if (mode == SortMode.NAME)
        {
            // Resolve each label once. Comparator-based sorting can otherwise ask for the
            // same name many times, causing needless config/string work.
            Map<String, String> sortNames = new HashMap<>();
            for (String code : normalized)
            {
                sortNames.put(code, labelService.getEffectiveName(code).toLowerCase(Locale.ROOT));
            }
            normalized.sort(Comparator
                .comparing((String code) -> sortNames.getOrDefault(code, code))
                .thenComparing(Function.identity(), String.CASE_INSENSITIVE_ORDER));
            return normalized;
        }

        List<String> saved = getSavedOrder(section);
        Set<String> visible = new LinkedHashSet<>(normalized);
        List<String> result = new ArrayList<>();

        for (String code : saved)
        {
            if (visible.remove(code))
            {
                result.add(code);
            }
        }

        // Newly seen codes are appended in their current interface order.
        result.addAll(visible);
        return result;
    }

    public List<String> move(FairyRingSection section, List<String> currentCodes, String code, int targetIndex)
    {
        List<String> current = currentCodes.stream()
            .map(FairyRingOrderService::normalizeCode)
            .filter(FairyRingDestination::isValidCode)
            .distinct()
            .collect(Collectors.toCollection(ArrayList::new));

        String normalizedCode = normalizeCode(code);
        if (!current.remove(normalizedCode))
        {
            return new ArrayList<>();
        }

        int boundedIndex = Math.max(0, Math.min(targetIndex, current.size()));
        current.add(boundedIndex, normalizedCode);

        // Preserve temporarily absent codes while the current section is rearranged.
        // Favorite re-entry is handled separately: when a code actually becomes a favorite
        // again, appendFavoritesToBottom(...) explicitly discards its old Favorite rank.
        saveOrderPreservingMissing(section, current);
        return new ArrayList<>(current);
    }

    /**
     * A ring newly added to Jagex Favorites is treated as a new priority and placed at
     * the bottom of the saved manual Favorites order. Removing it first therefore
     * intentionally discards its previous Favorite rank without deleting other settings.
     */
    public void appendFavoritesToBottom(List<String> currentFavoriteCodes, List<String> newlyFavoritedCodes)
    {
        if (newlyFavoritedCodes == null || newlyFavoritedCodes.isEmpty())
        {
            return;
        }

        List<String> saved = getSavedOrder(FairyRingSection.FAVORITES);
        Set<String> newSet = newlyFavoritedCodes.stream()
            .map(FairyRingOrderService::normalizeCode)
            .filter(FairyRingDestination::isValidCode)
            .collect(Collectors.toCollection(LinkedHashSet::new));

        // Make sure every already-existing favorite has a rank before the new entries.
        // This matters when Manual has never been moved/saved yet: adding a favorite must
        // still put it at the bottom rather than making it the only ranked (and first) code.
        if (currentFavoriteCodes != null)
        {
            for (String code : currentFavoriteCodes)
            {
                String normalized = normalizeCode(code);
                if (FairyRingDestination.isValidCode(normalized)
                    && !newSet.contains(normalized)
                    && !saved.contains(normalized))
                {
                    saved.add(normalized);
                }
            }
        }

        for (String normalized : newSet)
        {
            saved.remove(normalized);
            saved.add(normalized);
        }
        saveOrder(FairyRingSection.FAVORITES, saved);
    }

    public void saveOrder(FairyRingSection section, List<String> codes)
    {
        List<String> normalized = codes.stream()
            .map(FairyRingOrderService::normalizeCode)
            .filter(FairyRingDestination::isValidCode)
            .distinct()
            .collect(Collectors.toList());

        configManager.setConfiguration(
            FairyRingOrganizerConfig.GROUP,
            keyFor(section),
            Text.toCSV(normalized));
    }

    /**
     * Replaces the relative order of currently present codes while retaining previously
     * saved codes that are absent. Missing codes are inserted at their nearest historical
     * boundary so a temporary favorite transition does not destroy manual-order history.
     */
    private void saveOrderPreservingMissing(FairyRingSection section, List<String> currentOrderedCodes)
    {
        List<String> current = currentOrderedCodes.stream()
            .map(FairyRingOrderService::normalizeCode)
            .filter(FairyRingDestination::isValidCode)
            .distinct()
            .collect(Collectors.toCollection(ArrayList::new));

        List<String> previous = getSavedOrder(section);
        if (previous.isEmpty())
        {
            saveOrder(section, current);
            return;
        }

        Set<String> currentSet = new LinkedHashSet<>(current);
        List<String> missing = previous.stream()
            .filter(code -> !currentSet.contains(code))
            .collect(Collectors.toList());

        if (missing.isEmpty())
        {
            saveOrder(section, current);
            return;
        }

        List<String> merged = new ArrayList<>(current);
        for (String missingCode : missing)
        {
            int oldIndex = previous.indexOf(missingCode);
            String previousAnchor = null;
            String nextAnchor = null;

            for (int index = oldIndex - 1; index >= 0; index--)
            {
                if (currentSet.contains(previous.get(index)))
                {
                    previousAnchor = previous.get(index);
                    break;
                }
            }
            for (int index = oldIndex + 1; index < previous.size(); index++)
            {
                if (currentSet.contains(previous.get(index)))
                {
                    nextAnchor = previous.get(index);
                    break;
                }
            }

            int insertAt;
            if (previousAnchor != null)
            {
                insertAt = merged.indexOf(previousAnchor) + 1;
                // Keep multiple missing codes in their historical sequence after the anchor.
                while (insertAt < merged.size() && missing.contains(merged.get(insertAt))
                    && previous.indexOf(merged.get(insertAt)) < oldIndex)
                {
                    insertAt++;
                }
            }
            else if (nextAnchor != null)
            {
                insertAt = Math.max(0, merged.indexOf(nextAnchor));
            }
            else
            {
                insertAt = merged.size();
            }
            merged.add(Math.max(0, Math.min(insertAt, merged.size())), missingCode);
        }

        saveOrder(section, merged);
    }

    public List<String> getSavedOrder(FairyRingSection section)
    {
        String raw = configManager.getConfiguration(FairyRingOrganizerConfig.GROUP, keyFor(section));
        if (raw == null || raw.trim().isEmpty())
        {
            return new ArrayList<>();
        }

        return Text.fromCSV(raw).stream()
            .map(FairyRingOrderService::normalizeCode)
            .filter(FairyRingDestination::isValidCode)
            .distinct()
            .collect(Collectors.toCollection(ArrayList::new));
    }

    public void clearOrders()
    {
        configManager.unsetConfiguration(FairyRingOrganizerConfig.GROUP, FAVORITE_ORDER_KEY);
        configManager.unsetConfiguration(FairyRingOrganizerConfig.GROUP, REMAINING_ORDER_KEY);
    }

    public static boolean isOrderKey(String key)
    {
        return FAVORITE_ORDER_KEY.equals(key) || REMAINING_ORDER_KEY.equals(key);
    }

    private static String keyFor(FairyRingSection section)
    {
        return section == FairyRingSection.FAVORITES ? FAVORITE_ORDER_KEY : REMAINING_ORDER_KEY;
    }

    public static String normalizeCode(String code)
    {
        return FairyRingDestination.normalize(code);
    }
}

package com.fairyringorganizer;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

/**
 * Player-facing settings plus Organizer-owned persistence group names. Legacy key names are
 * intentionally retained where noted so existing RuneLite profiles are not silently reset.
 */
@ConfigGroup(FairyRingOrganizerConfig.GROUP)
public interface FairyRingOrganizerConfig extends Config
{
    String GROUP = "fairyringorganizer";
    String LABEL_GROUP = GROUP + ".labels";
    String QUICK_GROUP = GROUP + ".quick";

    @ConfigSection(
        name = "Configure interface",
        description = "Sort and customize the Configure list.",
        position = 0
    )
    String interfaceSection = "interface";

    @ConfigItem(
        keyName = "favoriteSort",
        name = "Favorites sort",
        description = "Sort favorited rings by name, code, or manual order.",
        section = interfaceSection,
        position = 0
    )
    default SortMode favoriteSort()
    {
        return SortMode.MANUAL;
    }

    @ConfigItem(
        keyName = "reorderFavoriteSubmenu",
        name = "Reorder Favourites submenu",
        description = "Match the right-click Favourites submenu to the Favorites order in Configure.",
        section = interfaceSection,
        position = 1
    )
    default boolean reorderFavoriteSubmenu()
    {
        return false;
    }

    @ConfigItem(
        keyName = "remainingSort",
        name = "Remaining codes sort",
        description = "Sort non-favorite rings by name, code, or manual order.",
        section = interfaceSection,
        position = 2
    )
    default SortMode remainingSort()
    {
        return SortMode.CODE;
    }

    @ConfigItem(
        keyName = "showDragHandles",
        name = "Show drag handles",
        description = "Show drag grips when using Manual sorting.",
        section = interfaceSection,
