package com.fairyringorganizer;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * Event wiring for client-side Fairy Ring list and menu presentation.
 *
 * The plugin does not synthesize or invoke server actions and does not inject mouse/keyboard
 * input. Game-facing edits are limited to the existing Fairy Ring Travel Log widgets/menu
 * entries plus the same native Search widget operation used by RuneLite's core Fairy Rings plugin.
 */
@PluginDescriptor(
    name = "Fairy Ring Organizer",
    description = "Sort, reorder, rename, and color fairy ring destinations",
    tags = {"fairy", "ring", "favorites", "favourites", "sort", "organize", "rename", "color", "colour"}
)
public class FairyRingOrganizerPlugin extends Plugin
{
    private volatile boolean active;

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ConfigManager configManager;

    @Inject
    private EventBus eventBus;

    @Inject
    private FairyRingMenuCaptureSubscriber menuCaptureSubscriber;

    @Inject
    private FairyRingInterfaceController interfaceController;

    @Inject
    private FairyRingDragController dragController;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private FairyRingDragOverlay dragOverlay;

    @Inject
    private FairyRingMenuController menuController;

    @Inject
    private FairyRingRenameController renameController;

    @Inject
    private FairyRingSearchController searchController;

    @Inject
    private FairyRingLabelService labelService;

    @Inject
    private FairyRingOrderService orderService;

    @Inject
    private FairyRingColorService colorService;

    @Inject
    private FairyRingFavoriteStateService favoriteStateService;

    @Inject
    private FairyRingQuickDestinationController quickDestinationController;

    @Inject
    private FairyRingQuickDestinationService quickDestinationService;

    @Provides
    FairyRingOrganizerConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(FairyRingOrganizerConfig.class);
    }

    @Override
    protected void startUp()
    {
        // Remove the obsolete Organizer-owned toggle that previously enabled labels from another
        // plugin. This migration touches only Fairy Ring Organizer configuration.
        configManager.unsetConfiguration(FairyRingOrganizerConfig.GROUP, "useFavouritesPluginLabels");

        // The early menu-capture handlers live on a separate subscriber because RuneLite's
        // EventBus requires subscribed methods to be named exactly on<EventClass>.
        eventBus.register(menuCaptureSubscriber);

        active = true;
        favoriteStateService.reset();
        colorService.invalidate();
        overlayManager.add(dragOverlay);
        dragController.start();
        clientThread.invokeLater(interfaceController::refreshNow);
    }

    @Override
    protected void shutDown()
    {
        active = false;
        eventBus.unregister(menuCaptureSubscriber);
        // Restore the already-open Configure interface immediately, but deliberately keep
        // every saved Organizer setting so re-enabling reapplies the user's preferences.
        clientThread.invoke(interfaceController::restoreNative);
        dragController.stop();
        overlayManager.remove(dragOverlay);
        favoriteStateService.reset();
        colorService.invalidate();
        menuController.clearIdentityCache();
    }

    @Override
    public void resetConfiguration()
    {
        // RuneLite's config panel calls this after its built-in Reset button restores all
        // declared config items to defaults. Clear our hidden per-code/order keys too.
        labelService.clearAllOwnLabels();
        orderService.clearOrders();
        quickDestinationService.clearAll();
        colorService.invalidate();
        favoriteStateService.reset();
        menuController.clearIdentityCache();
        if (active)
        {
            clientThread.invoke(() ->
            {
                interfaceController.restoreNative();
                interfaceController.resetRuntimeState();
                interfaceController.refreshNow();
            });
        }
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        if (event.getGroupId() == InterfaceID.FAIRYRINGS_LOG)
        {
            interfaceController.onWidgetLoaded();
        }
    }

    @Subscribe
    public void onScriptCallbackEvent(ScriptCallbackEvent event)
    {
        // Extend the same client-side search callbacks used by RuneLite's built-in Fairy
        // Rings plugin so custom labels are searchable. This never invokes a teleport.
        if (searchController.extendFilter(event))
        {
            interfaceController.onFairyRingBuildCallback();
        }
    }

    @Subscribe
    public void onScriptPostFired(ScriptPostFired event)
    {
        interfaceController.onScriptPostFired();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        String group = event.getGroup();
        if (FairyRingOrganizerConfig.GROUP.equals(group)
            || FairyRingOrganizerConfig.LABEL_GROUP.equals(group))
        {
            colorService.invalidate();
            if (FairyRingOrganizerConfig.LABEL_GROUP.equals(group))
            {
                labelService.invalidateAll();

                // Per-code labels are written by FairyRingRenameController. That controller
                // owns the live UI sequence because its ChatboxTextInput temporarily replaces
                // the Fairy Ring search field. A generic refresh here races that prompt and can
                // mistake the rename text in MESLAYERINPUT for an active Fairy Ring search.
                return;
            }

            // favoriteOrder/remainingOrder are hidden Organizer persistence keys. Manual drag
            // applies its new row geometry directly to the affected section, so reacting to the
            // synchronous ConfigChanged event with refreshSoon() would clear BOTH sections' forced
            // positions and cause the native icon flash we are avoiding.
            if (FairyRingOrganizerConfig.GROUP.equals(group)
                && FairyRingOrderService.isOrderKey(event.getKey()))
            {
                return;
            }

            // Sort selectors are also presentation-only changes. Repack only the section whose
            // mode changed using its already-settled live rows. This is the same no-clear strategy
            // used by Manual drops and prevents the green-heart/Remaining flicker that a full refresh
            // can expose between sort modes. Fall back to the guarded full refresh
            // only when there is no usable live section (closed/building/transitional interface).
            if (FairyRingOrganizerConfig.GROUP.equals(group)
                && ("favoriteSort".equals(event.getKey()) || "remainingSort".equals(event.getKey())))
            {
                FairyRingSection section = "favoriteSort".equals(event.getKey())
                    ? FairyRingSection.FAVORITES
                    : FairyRingSection.REMAINING;
                clientThread.invoke(() ->
                {
                    if (!interfaceController.applySortModeChange(section))
                    {
                        interfaceController.refreshSoon();
                    }
                });
                return;
            }

            interfaceController.refreshSoon();
        }
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event)
    {
        menuController.observeMenuEntryAdded(event.getMenuEntry());
        renameController.addRenameEntries(
            event.getOption(),
            event.getTarget(),
            event.getActionParam0(),
            event.getActionParam1(),
            event.getIdentifier());
    }

    // Early PostMenuSort capture is handled by FairyRingMenuCaptureSubscriber.
    @Subscribe(priority = -2)
    public void onPostMenuSort(PostMenuSort event)
    {
        if (!client.isMenuOpen())
        {
            menuController.processPendingMenu();
        }
    }

    // Early MenuOpened capture is handled by FairyRingMenuCaptureSubscriber.

    // Run late so Menu Entry Swapper has had a chance to construct/modify its submenus.
    // Our identity cache survives our own text changes.
    @Subscribe(priority = -2)
    public void onMenuOpened(MenuOpened event)
    {
        menuController.processPendingMenu();
        quickDestinationController.configurePerRingLeftClickChoices();

        // MES builds object-swap helper submenus from MenuOpened. The normal late pass
        // handles them immediately; retry once on the client thread for builds where the
        // submenu attachment finishes at the end of the event cycle.
        clientThread.invokeLater(() ->
        {
            menuController.refreshMenuEntrySwapperLabels();
            quickDestinationController.configurePerRingLeftClickChoices();
        });
    }

    @Subscribe
    public void onBeforeRender(BeforeRender event)
    {
        interfaceController.onBeforeRender();
    }

    @Subscribe
    public void onClientTick(ClientTick event)
    {
        interfaceController.onClientTick();
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        renameController.onGameTick();
        interfaceController.onGameTick();
        if (interfaceController.isOpen())
        {
            interfaceController.observeFavoriteMembership();
        }
    }
}

package com.fairyringorganizer;

import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.client.util.Text;

/**
 * Adds optional per-location Fairy Ring defaults to RuneLite's existing Swap left-click menu.
 *
 * The submenu entries modified here are RuneLite configuration helpers, not game actions.
 * Selecting a Favorite stores only an Organizer ring-location -> destination-code preference;
 * it does not invoke the Favorite action, and RuneLite's global Menu Entry Swapper object swap
 * remains unchanged. A teleport can occur only later from the user's normal click on an existing
 * Fairy Ring action entry.
 */
@Slf4j
public class FairyRingQuickDestinationController
{
    private static final String USE_GLOBAL_OPTION = "Use global default (this ring)";

    private final Client client;
    private final FairyRingOrganizerConfig config;
    private final FairyRingQuickDestinationService quickDestinationService;
    private final FairyRingLabelService labelService;
    private final FairyRingMenuController menuController;

    @Inject
    public FairyRingQuickDestinationController(
        Client client,
        FairyRingOrganizerConfig config,
        FairyRingQuickDestinationService quickDestinationService,
        FairyRingLabelService labelService,
        FairyRingMenuController menuController)
    {
        this.client = client;
        this.config = config;
        this.quickDestinationService = quickDestinationService;
        this.labelService = labelService;
        this.menuController = menuController;
    }

    /**
     * Rewire only Favorite choices inside RuneLite's existing Fairy Ring Swap left-click helper
     * submenu so a click stores the ring-local preference. These helper choices remain local
     * configuration actions; Configure, Last-destination, Zanaris, Favourites, Walk here, Reset,
     * and the entire Swap shift-click submenu remain RuneLite-owned.
     */
    public void configurePerRingLeftClickChoices()
    {
        if (!config.perRingFavorites())
        {
            return;
        }

        Menu root = client.getMenu();
        MenuEntry sourceEntry = menuController.findCurrentPhysicalRingEntry(root);
        if (sourceEntry == null)
        {
            return;
        }

        String ringKey = quickDestinationService.keyForMenuEntry(sourceEntry);
        if (ringKey == null)
        {
            return;
        }

        List<String> favoriteCodes = menuController.getFavoriteCodesSnapshot();
        Set<String> favoriteSet = new HashSet<>(favoriteCodes);
        boolean hasFavoriteSnapshot = !favoriteSet.isEmpty();

        String current = quickDestinationService.get(ringKey);

        for (MenuEntry entry : root.getMenuEntries())
        {
            if (!isFairyRingLeftClickSwapMenu(entry))
            {
                continue;
            }

            Menu submenu = entry.getSubMenu();
            if (submenu == null)
            {
                continue;
            }

            for (MenuEntry child : submenu.getMenuEntries())
            {
                String plain = plainOption(child);

                // When this physical ring already has an Organizer override, choosing
                // RuneLite's normal Configure option must first remove that local override.
                // Then preserve/invoke MES's original callback so Configure is still saved as
                // the global fallback for unconfigured rings. Without this wrapper, MES would
                // switch globally to Configure while Organizer immediately reapplied the stale
                // per-ring destination, making it look impossible to switch this ring back.
                if (current != null && plain.equalsIgnoreCase("Configure"))
                {
                    // This is MES's existing RUNELITE configuration callback for choosing
                    // Configure as the object swap; it is not a RuneScape/game-action callback.
                    final java.util.function.Consumer<MenuEntry> originalOnClick = child.onClick();
                    child.onClick(clicked ->
                    {
                        boolean hadLocalDefault = quickDestinationService.get(ringKey) != null;
                        quickDestinationService.clear(ringKey);
                        if (hadLocalDefault && config.debugDiagnostics())
                        {
                            log.debug("Fairy Ring Organizer: ring default cleared: ring={} source=Configure", ringKey);
                        }
                        if (originalOnClick != null)
                        {
                            originalOnClick.accept(clicked);
                        }
                    });
                    continue;
                }

                // Last-destination can carry the same destination code as a Favorite.
                // It must remain RuneLite's normal global Last-destination choice.
                if (plain.regionMatches(true, 0, "Last", 0, 4))
                {
                    continue;
                }

                String code = menuController.resolveMenuCode(child);
                if (code == null)
                {
                    continue;
                }

                // Normally the populated Jagex Favourites submenu supplies the membership
                // snapshot. If another presentation plugin wraps that submenu so the snapshot
                // is unavailable, fall back to the ordinary destination-code choices already present
                // in RuneLite's Swap left-click helper. Last-destination is excluded above and
                // Zanaris is excluded here, so this fallback cannot turn those global special
                // choices into per-ring Favorites.
                if (hasFavoriteSnapshot)
                {
                    if (!favoriteSet.contains(code))
                    {
                        continue;
                    }
                }
                else if (plain.regionMatches(true, 0, "Zanaris", 0, 7))
                {
                    continue;
                }

                final String selectedCode = code;
                child.setOption(formatChoiceLabel(code, code.equals(current)))
                    .onClick(clicked ->
                    {
                        boolean changed = !selectedCode.equals(quickDestinationService.get(ringKey));
                        quickDestinationService.set(ringKey, selectedCode);
                        if (changed && config.debugDiagnostics())
                        {
                            log.debug("Fairy Ring Organizer: ring default set: ring={} code={}", ringKey, selectedCode);
                        }
                    });
            }

            if (current != null && !containsOption(submenu, USE_GLOBAL_OPTION))
            {
                submenu.createMenuEntry(0)
                    .setOption(USE_GLOBAL_OPTION)
                    .setType(MenuAction.RUNELITE)
                    .onClick(clicked ->
                    {
                        boolean hadLocalDefault = quickDestinationService.get(ringKey) != null;
                        quickDestinationService.clear(ringKey);
                        if (hadLocalDefault && config.debugDiagnostics())
                        {
                            log.debug("Fairy Ring Organizer: ring default cleared: ring={} source=global", ringKey);
                        }
                    });
            }
        }

    }

    private static boolean isFairyRingLeftClickSwapMenu(MenuEntry entry)
    {
        if (entry == null)
        {
            return false;
        }

        String target = Text.removeTags(entry.getTarget() == null ? "" : entry.getTarget());
        if (!target.toLowerCase(Locale.ROOT).contains("fairy ring"))
        {
            return false;
        }

        return plainOption(entry).equalsIgnoreCase("Swap left-click");
    }

    private static boolean containsOption(Menu menu, String option)
    {
        for (MenuEntry entry : menu.getMenuEntries())
        {
            if (plainOption(entry).equalsIgnoreCase(option))
            {
                return true;
            }
        }
        return false;
    }

    private String formatChoiceLabel(String code, boolean selected)
    {
        String label;
        if (!config.labelMenus())
        {
            label = code;
        }
        else
        {
            String name = labelService.getEffectiveName(code);
            label = config.showCodeInMenuLabel() ? name + " (" + code + ')' : name;
        }

        return selected ? "* " + label : label;
    }

    private static String plainOption(MenuEntry entry)
    {
        if (entry == null)
        {
            return "";
        }
        return Text.removeTags(entry.getOption() == null ? "" : entry.getOption()).trim();
    }
}

package com.fairyringorganizer;

import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.config.ConfigManager;

/**
 * Persists a preferred favorite destination for an individual physical fairy ring.
 *
 * The source ring is keyed by its world tile. The saved value is only a fairy-ring code in
 * RuneLite ConfigManager; no game action, callback, or Menu Entry Swapper setting is persisted
 * or modified here.
 */
public class FairyRingQuickDestinationService
{
    private final Client client;
    private final ConfigManager configManager;

    @Inject
    public FairyRingQuickDestinationService(Client client, ConfigManager configManager)
    {
        this.client = client;
        this.configManager = configManager;
    }

    /**
     * Resolve a physical Fairy Ring from the actual object menu entry. Using the
     * MenuEntry world-view id avoids treating every copy of the shared Fairy Ring
     * object id as one global location (which is exactly how Menu Entry Swapper
     * stores its normal object swap).
     */
    public String keyForMenuEntry(MenuEntry entry)
    {
        if (entry == null)
        {
            return null;
        }

        WorldView worldView = client.getWorldView(entry.getWorldViewId());
        if (worldView == null)
        {
            return keyForScene(entry.getParam0(), entry.getParam1());
        }

        WorldPoint worldPoint = WorldPoint.fromScene(
            worldView, entry.getParam0(), entry.getParam1(), worldView.getPlane());
        return keyForWorldPoint(worldPoint);
    }

    public String keyForScene(int sceneX, int sceneY)
    {
        WorldPoint worldPoint = WorldPoint.fromScene(client, sceneX, sceneY, client.getPlane());
        return keyForWorldPoint(worldPoint);
    }

    private static String keyForWorldPoint(WorldPoint worldPoint)
    {
        if (worldPoint == null)
        {
            return null;
        }

        return "p" + worldPoint.getPlane() + "_x" + worldPoint.getX() + "_y" + worldPoint.getY();
    }

    public String get(String ringKey)
    {
        if (ringKey == null || ringKey.isEmpty())
        {
            return null;
        }

        String raw = configManager.getConfiguration(FairyRingOrganizerConfig.QUICK_GROUP, ringKey);
        String normalized = FairyRingOrderService.normalizeCode(raw);
        return FairyRingDestination.isValidCode(normalized) ? normalized : null;
    }

    public void set(String ringKey, String code)
    {
        if (ringKey == null || ringKey.isEmpty())
        {
            return;
        }

        String normalized = FairyRingOrderService.normalizeCode(code);
        if (!FairyRingDestination.isValidCode(normalized))
        {
            return;
        }

        configManager.setConfiguration(FairyRingOrganizerConfig.QUICK_GROUP, ringKey, normalized);
    }

    public void clear(String ringKey)
    {
        if (ringKey != null && !ringKey.isEmpty())
        {
            configManager.unsetConfiguration(FairyRingOrganizerConfig.QUICK_GROUP, ringKey);
        }
    }

    public void clearAll()
    {
        List<String> keys = configManager.getConfigurationKeys(FairyRingOrganizerConfig.QUICK_GROUP + ".");
        for (String key : keys)
        {
            int lastDot = key.lastIndexOf('.');
            if (lastDot <= 0 || lastDot >= key.length() - 1)
            {
                continue;
            }

            configManager.unsetConfiguration(key.substring(0, lastDot), key.substring(lastDot + 1));
        }
    }
}

package com.fairyringorganizer;

import java.util.Locale;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.SoundEffectID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.game.chatbox.ChatboxTextInput;
import net.runelite.client.util.Text;

/**
 * Adds local Rename/Reset actions to Configure rows and coordinates those edits with RuneLite's
 * native Fairy Ring search input. The ChatboxTextInput is Organizer configuration UI, not game
 * chat, and no RuneScape action is created or invoked by these entries.
 */
@Slf4j
public class FairyRingRenameController
{
    private final Client client;
    private final ClientThread clientThread;
    private final ChatboxPanelManager chatboxPanelManager;
    private final FairyRingLabelService labelService;
    private final FairyRingInterfaceController interfaceController;
    private final FairyRingSearchController searchController;
    private final FairyRingOrganizerConfig config;
    private ChatboxTextInput labelInput;

    @Inject
    public FairyRingRenameController(
        Client client,
        ClientThread clientThread,
        ChatboxPanelManager chatboxPanelManager,
        FairyRingLabelService labelService,
        FairyRingInterfaceController interfaceController,
        FairyRingSearchController searchController,
        FairyRingOrganizerConfig config)
    {
        this.client = client;
        this.clientThread = clientThread;
        this.chatboxPanelManager = chatboxPanelManager;
        this.labelService = labelService;
        this.interfaceController = interfaceController;
        this.searchController = searchController;
        this.config = config;
    }

    public void addRenameEntries(String option, String target, int param0, int param1, int identifier)
    {
        if (WidgetUtil.componentToInterface(param1) != InterfaceID.FAIRYRINGS_LOG
            || !"Use code".equals(option)
            || target == null
            || target.isEmpty())
        {
            return;
        }

        String code = parseCodeFromTarget(target);
        if (!FairyRingDestination.isValidCode(code))
        {
            return;
        }

        client.getMenu().createMenuEntry(-1)
            .setParam0(param0)
            .setParam1(param1)
            .setIdentifier(identifier)
            .setTarget(target)
            .setOption("Rename")
            .setType(MenuAction.RUNELITE)
            .onClick(entry -> openRename(code));

        if (labelService.getOwnCustomLabel(code) != null)
        {
            client.getMenu().createMenuEntry(-1)
                .setParam0(param0)
                .setParam1(param1)
                .setIdentifier(identifier)
                .setTarget(target)
                .setOption("Reset name")
                .setType(MenuAction.RUNELITE)
                .onClick(entry -> {
                    boolean searchWasOpen = searchController.isSearchActive()
                        || searchController.isSearchInputPending();
                    labelService.clearOwnCustomLabel(code);
                    if (config.debugDiagnostics())
                    {
                        log.debug("Fairy Ring Organizer: name reset: code={} searchActive={}", code, searchWasOpen);
                    }
                    refreshAfterImmediateLabelChange(searchWasOpen);
                });
        }
    }

    public void onGameTick()
    {
        // Do not use FairyRingInterfaceController.isOpen() to decide whether the rename prompt
        // should stay alive. Opening a RuneLite ChatboxTextInput can temporarily hide/rebuild the
        // FAIRYRINGS_LOG list containers even though the main fairy-ring chooser is still open.
        // That can make Organizer's presentation lifecycle briefly report closed and would
        // immediately dismiss the text input on the next game tick.
        //
        // Match RuneLite's own Fairy Rings "Edit Tags" lifecycle instead: the main CONFIRM
        // widget is the reliable indicator that the fairy-ring chooser itself is still open.
        Widget fairyRingTeleportButton = client.getWidget(InterfaceID.Fairyrings.CONFIRM);
        boolean fairyRingWidgetOpen = fairyRingTeleportButton != null && !fairyRingTeleportButton.isHidden();
        boolean inputOpen = labelInput != null && chatboxPanelManager.getCurrentInput() == labelInput;
        if (!fairyRingWidgetOpen && inputOpen)
        {
            chatboxPanelManager.close();
        }
    }

    private void openRename(String code)
    {
        client.playSoundEffect(SoundEffectID.UI_BOOP);
        String existing = labelService.getOwnCustomLabel(code);
        if (existing == null)
        {
            existing = labelService.getEffectiveName(code);
        }

        String prompt = "Name for " + code + " (max "
            + FairyRingLabelService.MAX_CUSTOM_LABEL_LENGTH + "):";
        labelInput = chatboxPanelManager.openTextInput(prompt)
            .value(existing)
            .onDone(value ->
            {
                labelService.setOwnCustomLabel(code, value);

                // Match RuneLite Fairy Rings' Edit Tags lifecycle: the local ChatboxTextInput
                // temporarily owns the message layer, then the native Fairy Ring Search UI is
                // reopened only after that local input has released it. This is UI state only;
                // no chat message is inserted, modified, or sent.
                int labelLength = value == null ? 0 : value.length();
                clientThread.invokeLater(() -> clientThread.invokeLater(
                    () -> refreshAfterLabelChange(code, labelLength)));
            })
            .build();
    }

    /**
     * Rename always returns to the native Fairy Ring Search input after Enter. This deliberately
     * mirrors RuneLite Fairy Rings' Edit Tags flow and avoids trying to rediscover Search state
     * after the temporary ChatboxTextInput has already displaced the shared message layer.
     */
    private void refreshAfterLabelChange(String code, int labelLength)
    {
        // During a live search, update labels without taking ownership of filtering; outside
        // search this falls back to the normal Configure refresh. Rename then returns through
        // RuneLite's native Fairy Ring Search operation.
        interfaceController.refreshLabelsDuringSearch();
        clientThread.invokeLater(() -> openSearch(code, labelLength));
    }

    /**
     * Reset name is different from Rename: there is no ChatboxTextInput and the native Fairy Ring
     * search field is still open when the menu callback runs. Calling openSearch() once in that
     * state toggles the search UI closed. Refresh the native filter by cycling that same native
     * operation closed->open synchronously in one client task while preserving both search varcs.
     * No intermediate closed state is rendered, and Jagex remains the owner of filtered geometry.
     */
    private void refreshAfterImmediateLabelChange(boolean searchWasOpen)
    {
        if (!searchWasOpen)
        {
            interfaceController.refreshNow();
            return;
        }

        interfaceController.refreshLabelsDuringSearch();
        clientThread.invokeLater(this::refreshOpenSearch);
    }

    private void refreshOpenSearch()
    {
        Widget search = client.getWidget(InterfaceID.FairyringsLog.SEARCH);
        if (search == null || search.getOnOpListener() == null)
        {
            return;
        }

        String filter = client.getVarcStrValue(VarClientID.FAIRYRINGS_SEARCHSTRING);
        String messageInput = client.getVarcStrValue(VarClientID.MESLAYERINPUT);
        if (filter == null)
        {
            filter = "";
        }
        if (messageInput == null)
        {
            messageInput = "";
        }

        // First invocation closes the already-open search and rebuilds the list. Restore the
        // query immediately, then invoke the same native operation again to reopen Search before
        // the next rendered client frame.
        runSearchOp(search);
        client.setVarcStrValue(VarClientID.FAIRYRINGS_SEARCHSTRING, filter);
        client.setVarcStrValue(VarClientID.MESLAYERINPUT, "");
        runSearchOp(search);

        // Preserve the exact Fairy Ring Search input representation (including its native
        // trailing cursor marker, when present) and canonical filter after reopening. These varcs
        // are the Fairy Ring Search/message-layer UI state, not an outgoing chat message.
        client.setVarcStrValue(VarClientID.FAIRYRINGS_SEARCHSTRING, filter);
        client.setVarcStrValue(VarClientID.MESLAYERINPUT, messageInput);
    }

    private void openSearch(String code, int labelLength)
    {
        Widget search = client.getWidget(InterfaceID.FairyringsLog.SEARCH);
        boolean searchAvailable = search != null && search.getOnOpListener() != null;
        if (searchAvailable)
        {
            client.setVarcStrValue(VarClientID.MESLAYERINPUT, "");
            runSearchOp(search);
        }

        if (config.debugDiagnostics())
        {
            String query = client.getVarcStrValue(VarClientID.FAIRYRINGS_SEARCHSTRING);
            log.debug(
                "Fairy Ring Organizer: name changed: code={} chars={} searchRestored={} queryChars={}",
                code, labelLength, searchAvailable, query == null ? 0 : query.length());
        }
    }

    /**
     * Runs the Search widget's own op listener, matching RuneLite core FairyRingPlugin.openSearch().
     * This is a client-interface operation: it opens/closes the Fairy Ring search field and does
     * not select dials, confirm a destination, inject input, or send a server action.
     */
    private void runSearchOp(Widget search)
    {
        client.createScriptEventBuilder(search.getOnOpListener())
            .setOp(1)
            .build()
            .run();
    }

    private static String parseCodeFromTarget(String target)
    {
        return Text.removeTags(target).replace(" ", "").trim().toUpperCase(Locale.ROOT);
    }
}

package com.fairyringorganizer;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.api.widgets.Widget;

/**
 * A logical row in one of the two Jagex fairy ring containers.
 * A row can contain more than one top-level widget; offsets are retained while the row moves.
 */
public final class FairyRingRow
{
    private final String code;
    private final FairyRingSection section;
    private final Widget container;
    private int baseY;
    private final List<RowWidget> widgets;
    private final Widget labelWidget;

    public FairyRingRow(
        String code,
        FairyRingSection section,
        Widget container,
        int baseY,
        int nativeOriginalY,
        List<Widget> widgets,
        Widget labelWidget)
    {
        this.code = code;
        this.section = section;
        this.container = container;
        this.baseY = baseY;
        List<RowWidget> positioned = new ArrayList<>();
        for (Widget widget : widgets)
        {
            // Preserve the widget's *rendered* native geometry, not its originalY input.
            // The fairy-ring code and destination-label widgets can share originalY while
            // ending up at different relative Y coordinates because of their positioning
            // modes. Using relativeY keeps the exact native two-line row presentation.
            // setForcedPosition(-1, -1) is RuneLite's documented clear sentinel. During
            // a favorite/unfavorite rebuild the old row widgets can briefly report -1 for
            // their relative coordinates before Jagex revalidates them. Using those -1s as
            // real geometry produces enormous negative offsets and stacks the entire list.
            // Fall back to the newly rebuilt native original coordinates for that transient
            // window; on a settled interface the normal relative coordinates are used.
            int effectiveX = FairyRingWidgetScanner.effectiveRelativeX(widget);
            int relativeY = widget.getRelativeY();
            int originalOffset = widget.getOriginalY() - nativeOriginalY;
            int candidateY = relativeY >= 0 ? relativeY : widget.getOriginalY();

            // An unfavorite rebuild can leave one half of a logical row on the previous
            // Organizer coordinate while the destination label has already returned to its
            // native position. This can happen even when the stale member still reports a
            // non-negative relativeY, so checking only for the (-1,-1) clear sentinel is not
            // sufficient. Native members of a fairy-ring row share essentially the same Y;
            // if either the original or rendered candidate is far from the label anchor,
            // normalize that member back onto the row rather than preserving a bogus offset.
            int effectiveY;
            if (Math.abs(originalOffset) > 8 || Math.abs(candidateY - baseY) > 16)
            {
                effectiveY = baseY;
            }
            else
            {
                effectiveY = candidateY;
            }
            positioned.add(new RowWidget(
                widget,
                effectiveX,
                effectiveY - baseY));
        }
        this.widgets = Collections.unmodifiableList(positioned);
        this.labelWidget = labelWidget;
    }

    public String getCode()
    {
        return code;
    }

    public FairyRingSection getSection()
    {
        return section;
    }

    public Widget getContainer()
    {
        return container;
    }

    public int getBaseY()
    {
        return baseY;
    }

    public Widget getLabelWidget()
    {
        return labelWidget;
    }

    /** Package-level access for native-state snapshots; callers must stay on the client thread. */
    List<Widget> getMemberWidgets()
    {
        List<Widget> result = new ArrayList<>();
        for (RowWidget positioned : widgets)
        {
            result.add(positioned.widget);
        }
        return Collections.unmodifiableList(result);
    }

    /**
     * Returns the visible bounds occupied by the widgets in this logical row.
     * Calculated on the client thread so drag placement does not rely on one specific
     * Jagex child (such as the destination-name text) always existing.
     */
    public Rectangle getBounds()
    {
        Rectangle result = null;
        for (RowWidget positioned : widgets)
        {
            Rectangle bounds = positioned.widget.getBounds();
            if (bounds == null || bounds.isEmpty())
            {
                continue;
            }

            result = result == null ? new Rectangle(bounds) : result.union(bounds);
        }
        return result;
    }

    /**
     * Height of the logical row using the normalized member offsets captured at scan time.
     * Unlike Widget#getBounds(), this does not depend on stale screen bounds while RuneLite
     * is clearing/reapplying forced positions during an in-place list rebuild.
     */
    public int getLogicalHeight()
    {
        int minY = 0;
        int maxY = 0;
        boolean seen = false;
        for (RowWidget positioned : widgets)
        {
            if (positioned.widget == null || positioned.widget.isSelfHidden())
            {
                continue;
            }

            int height = Math.max(0, positioned.widget.getHeight());
            if (!seen)
            {
                minY = positioned.offsetY;
                maxY = positioned.offsetY + height;
                seen = true;
            }
            else
            {
                minY = Math.min(minY, positioned.offsetY);
                maxY = Math.max(maxY, positioned.offsetY + height);
            }
        }
        return seen ? Math.max(1, maxY - minY) : 1;
    }

    public void moveTo(int newBaseY)
    {
        for (RowWidget positioned : widgets)
        {
            // RuneLite's forced position is intentionally used instead of repeatedly
            // rewriting originalY. Every member here was discovered inside the Fairy Ring Travel
            // Log by FairyRingWidgetScanner; this changes row position only, not width/height or
            // any game-world/combat/inventory click zone.
            positioned.widget.setForcedPosition(positioned.relativeX, newBaseY + positioned.offsetY);
        }
        baseY = newBaseY;
    }

    private static final class RowWidget
    {
        private final Widget widget;
        private final int relativeX;
        private final int offsetY;

        private RowWidget(Widget widget, int relativeX, int offsetY)
        {
            this.widget = widget;
            this.relativeX = relativeX;
            this.offsetY = offsetY;
        }
    }
}

package com.fairyringorganizer;

import java.util.Locale;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;

/**
 * Integrates custom labels with Jagex/RuneLite's existing fairy-ring search.
 * This only changes whether an existing row passes the client-side filter callback.
 */
public class FairyRingSearchController
{
    private static final String FILTER_FAVORITE = "fairyringFilterFavorite";
    private static final String FILTER_DB_ROW = "fairyringFilterDbrow";

    private final Client client;
    private final FairyRingLabelService labelService;

    @Inject
    public FairyRingSearchController(Client client, FairyRingLabelService labelService)
    {
        this.client = client;
        this.labelService = labelService;
    }

    public boolean isSearchActive()
    {
        // Match the native UI state, not our normalized matching text. A whitespace-only
        // search still causes Jagex to run its filter/build scripts, so treating it as
        // "inactive" makes Organizer fight those scripts and repeatedly reapply sorting.
        return !getRawFilter().isEmpty();
    }

    /**
     * The shared message-layer input can receive the first typed character slightly before
     * FAIRYRINGS_SEARCHSTRING is updated. RuneScape appends a literal '*' cursor marker to this
     * value, including when the field is otherwise empty. Strip only that final cursor marker so
     * '*' means no pending search while 'e*' correctly means the user has started typing.
     *
     * Whitespace is deliberately preserved: a value such as ' *' is still a native search
     * transition even though it does not meaningfully filter the list.
     */
    public boolean isSearchInputPending()
    {
        if (isSearchActive())
        {
            return false;
        }

        return !getMessageLayerSearchText().isEmpty();
    }

    /** Returns true when this was one of the two fairy-ring filter callbacks. */
    public boolean extendFilter(ScriptCallbackEvent event)
    {
        String eventName = event.getEventName();
        if (!FILTER_FAVORITE.equals(eventName) && !FILTER_DB_ROW.equals(eventName))
        {
            return false;
        }

        String code = extractCode(eventName);
        if (!FairyRingDestination.isValidCode(code))
        {
            return true;
        }

        String filter = getFilter();
        if (filter.isEmpty())
        {
            return true;
        }

        String effectiveName = labelService.getEffectiveName(code).toLowerCase(Locale.ROOT);
        if (code.toLowerCase(Locale.ROOT).contains(filter) || effectiveName.contains(filter))
        {
            int stackSize = client.getIntStackSize();
            if (stackSize > 0)
            {
                // These callbacks expose their boolean "include this existing row" result in
                // the top int-stack slot. RuneLite's core Fairy Rings plugin uses the same
                // contract for code/tag matches; Organizer only adds custom-name/code matches.
                client.getIntStack()[stackSize - 1] = 1;
            }
        }
        return true;
    }

    private String extractCode(String eventName)
    {
        int stackSize = client.getIntStackSize();
        if (stackSize < 2)
        {
            return "";
        }

        if (FILTER_FAVORITE.equals(eventName))
        {
            Widget widget = client.getWidget(client.getIntStack()[stackSize - 2]);
            return widget == null ? "" : FairyRingOrderService.normalizeCode(widget.getText());
        }

        Object[] values = client.getDBTableField(
            client.getIntStack()[stackSize - 2],
            DBTableID.Fairyring.COL_CODE,
            0);
        if (values == null || values.length == 0 || !(values[0] instanceof String))
        {
            return "";
        }
        return FairyRingOrderService.normalizeCode((String) values[0]);
    }

    private String getFilter()
    {
        return getRawFilter().trim().toLowerCase(Locale.ROOT);
    }

    private String getRawFilter()
    {
        String filter = client.getVarcStrValue(VarClientID.FAIRYRINGS_SEARCHSTRING);
        return filter == null ? "" : filter;
    }

    private String getMessageLayerSearchText()
    {
        String input = client.getVarcStrValue(VarClientID.MESLAYERINPUT);
        if (input == null || input.isEmpty())
        {
            return "";
        }

        // The native message-layer input renders its insertion cursor as a trailing '*'.
        // Remove exactly one final marker; do not trim spaces because whitespace itself keeps
        // the native fairy-ring filter scripts active.
        if (input.charAt(input.length() - 1) == '*')
        {
            input = input.substring(0, input.length() - 1);
        }
        return input;
    }
}

package com.fairyringorganizer;

public enum FairyRingSection
{
    FAVORITES,
    REMAINING
}

package com.fairyringorganizer;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import javax.inject.Inject;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

/**
 * Converts only the live Fairy Ring Travel Log Favorites/Remaining containers into logical rows.
 *
 * Discovery is intentionally isolated from sorting and does not traverse unrelated interfaces.
 * If Jagex changes the Travel Log widget hierarchy, this is the primary adaptation boundary.
 */
public class FairyRingWidgetScanner
{
    private static final Pattern CODE_PATTERN = Pattern.compile("^[A-D][I-L][P-S]$");
    static final String HANDLE_NAME = "Fairy Ring Organizer Drag Handle";

    @Inject
    public FairyRingWidgetScanner()
    {
    }

    public List<FairyRingRow> scan(Widget container, FairyRingSection section)
    {
        if (container == null || container.isHidden())
        {
            return new ArrayList<>();
        }

        // Jagex exposes the row presentation through a mixture of dynamic/static/nested
        // children. In the live FairyringsLog hierarchy, CONTENTS can also expose the FAVES
        // subtree through its nested view. Never allow that nested Favorites subtree to be
        // treated as Remaining rows.
        List<Widget> topLevel = directChildren(container).stream()
            .filter(widget -> widget != null && !isOrganizerHandle(widget))
            .filter(widget -> belongsToSection(widget, container, section))
            .collect(Collectors.toList());
        if (topLevel.isEmpty())
        {
            return new ArrayList<>();
        }

        // The code text widget is the row anchor. Destination-label widgets expose the same
        // code in Widget#getName(), which gives us an identity link that does not depend on
        // current Y positions. This is important because Jagex may revalidate positions after
        // we have already applied an Organizer order.
        Map<String, Widget> anchorsByCode = new LinkedHashMap<>();
        for (Widget child : topLevel)
        {
            String code = codeFromText(child);
            if (code != null)
            {
                anchorsByCode.putIfAbsent(code, child);
            }
        }

        Set<Widget> claimed = identitySet();
        List<FairyRingRow> rows = new ArrayList<>();

        for (Map.Entry<String, Widget> anchorEntry : anchorsByCode.entrySet())
        {
            String code = anchorEntry.getKey();
            Widget anchor = anchorEntry.getValue();
            List<Widget> members = new ArrayList<>();

            // First attach widgets that explicitly identify themselves as this code, either
            // through their visible code text or their operation/name metadata. Identity is
            // deliberately resolved before geometry. During an unfavorite rebuild Jagex can
            // temporarily rewrite the reusable plain-code widget's originalY using the old
            // Organizer-packed order, while the destination label already has the correct
            // native row coordinate. The code widget remains a good identity anchor, but not
            // a trustworthy geometry anchor in that transition.
            for (Widget candidate : topLevel)
            {
                if (claimed.contains(candidate))
                {
                    continue;
                }

                String identityCode = codeIdentity(candidate);
                if (code.equals(identityCode))
                {
                    members.add(candidate);
                }
            }

            if (!members.contains(anchor))
            {
                members.add(anchor);
            }

            Widget labelWidget = findBestLabelWidget(members, code);
            Widget geometryAnchor = labelWidget != null && !labelWidget.isSelfHidden() ? labelWidget : anchor;
            int nativeOriginalY = geometryAnchor.getOriginalY();
            int baseY = effectiveRelativeY(geometryAnchor);

            // Row icons/action graphics do not carry the code. Attach them by the destination
            // label's native row Y, not by the plain code widget's Y: during an in-place Favorite
            // rebuild the reusable code widget can already reflect a compacted/transitional Y.
            for (Widget candidate : topLevel)
            {
                if (claimed.contains(candidate) || members.contains(candidate))
                {
                    continue;
                }

                if (codeIdentity(candidate) == null
                    && candidate.getOriginalY() == nativeOriginalY
                    && candidate.getOriginalX() > 1)
                {
                    members.add(candidate);
                }
            }

            claimed.addAll(members);
            rows.add(new FairyRingRow(code, section, container, baseY, nativeOriginalY, members, labelWidget));
        }

        rows.sort(Comparator.comparingInt(FairyRingRow::getBaseY));

        return rows;
    }

    /**
     * Return the rendered parent-relative Y when it is valid. RuneLite documents (-1, -1)
     * as the sentinel used to clear a forced widget position; immediately after that clear,
     * the live client can briefly report relativeY=-1 until the interface is revalidated.
     * The fairy-ring build script has already written the new native originalY by then, so
     * originalY is the correct geometry fallback for this interface.
     */
    static int effectiveRelativeY(Widget widget)
    {
        int relativeY = widget.getRelativeY();
        return relativeY >= 0 ? relativeY : widget.getOriginalY();
    }

    static int effectiveRelativeX(Widget widget)
    {
        int relativeX = widget.getRelativeX();
        return relativeX >= 0 ? relativeX : widget.getOriginalX();
    }

    private static boolean belongsToSection(Widget widget, Widget requestedContainer, FairyRingSection section)
    {
        if (section == FairyRingSection.REMAINING)
        {
            if (widget.getId() == InterfaceID.FairyringsLog.FAVES
                || hasAncestorId(widget, InterfaceID.FairyringsLog.FAVES))
            {
                return false;
            }
        }

        return true;
    }

    private static boolean hasAncestorId(Widget widget, int widgetId)
    {
        for (Widget parent = widget == null ? null : widget.getParent(); parent != null; parent = parent.getParent())
        {
            if (parent.getId() == widgetId)
            {
                return true;
            }
        }
        return false;
    }

    private static String codeFromText(Widget widget)
    {
        String normalized = normalizeWidgetText(widget == null ? null : widget.getText());
        return CODE_PATTERN.matcher(normalized).matches() && FairyRingDestination.isValidCode(normalized)
            ? normalized : null;
    }

    private static String codeIdentity(Widget widget)
    {
        String fromText = codeFromText(widget);
        if (fromText != null)
        {
            return fromText;
        }

        String normalizedName = normalizeWidgetText(widget == null ? null : widget.getName());
        return CODE_PATTERN.matcher(normalizedName).matches() && FairyRingDestination.isValidCode(normalizedName)
            ? normalizedName : null;
    }

    private static Widget findBestLabelWidget(List<Widget> roots, String code)
    {
        List<Widget> candidates = new ArrayList<>();
        Set<Widget> visited = identitySet();
        for (Widget root : roots)
        {
            collectTextWidgets(root, candidates, visited);
        }

        return candidates.stream()
            .filter(widget -> {
                String text = Text.removeTags(nullToEmpty(widget.getText())).trim();
                String normalized = text.replace(" ", "").toUpperCase();
                return !text.isEmpty()
                    && !normalized.equals(code)
                    && !CODE_PATTERN.matcher(normalized).matches();
            })
            .max(Comparator.comparingInt(widget -> Text.removeTags(nullToEmpty(widget.getText())).length()))
            .orElse(null);
    }

    private static void collectTextWidgets(Widget widget, List<Widget> output, Set<Widget> visited)
    {
        if (widget == null || !visited.add(widget) || isOrganizerHandle(widget))
        {
            return;
        }

        if (widget.getText() != null && !widget.getText().isEmpty())
        {
            output.add(widget);
        }

        for (Widget child : directChildren(widget))
        {
            collectTextWidgets(child, output, visited);
        }
    }

    /**
     * RuneLite exposes static, dynamic, and nested child views. They can contain the same
     * Widget object more than once, so object identity is used rather than widget id.
     */
    private static List<Widget> directChildren(Widget widget)
    {
        Set<Widget> unique = identitySet();
        addAll(unique, widget.getDynamicChildren());
        addAll(unique, widget.getStaticChildren());
        addAll(unique, widget.getNestedChildren());
        return new ArrayList<>(unique);
    }

    private static void addAll(Set<Widget> unique, Widget[] widgets)
    {
        if (widgets == null)
        {
            return;
        }

        for (Widget widget : widgets)
        {
            if (widget != null && !isOrganizerHandle(widget))
            {
                unique.add(widget);
            }
        }
    }

    private static Set<Widget> identitySet()
    {
        return Collections.newSetFromMap(new IdentityHashMap<>());
    }

    private static String normalizeWidgetText(String text)
    {
        return Text.removeTags(nullToEmpty(text)).replace(" ", "").trim().toUpperCase();
    }

    private static boolean isOrganizerHandle(Widget widget)
    {
        return widget != null && widget.getName() != null && widget.getName().startsWith(HANDLE_NAME);
    }

    private static String nullToEmpty(String value)
    {
        return value == null ? "" : value;
    }
}

package com.fairyringorganizer;

public enum SortMode
{
    MANUAL("Manual"),
    NAME("Name (A-Z)"),
    CODE("Code (A-Z)");

    private final String displayName;

    SortMode(String displayName)
    {
        this.displayName = displayName;
    }

    @Override
    public String toString()
    {
        return displayName;
    }
}

package com.fairyringorganizer;

import java.awt.Color;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

public class FairyRingColorServiceTest
{
    @Test
    public void parsesNamedAndHexColors()
    {
        Map<String, Color> colors = FairyRingColorService.parse(
            "DJR, Red\n" +
            "DKR, #12AB34\n" +
            "BJS, 0xABCDEF\n");

        Assert.assertEquals(new Color(0xFF0000), colors.get("DJR"));
        Assert.assertEquals(new Color(0x12AB34), colors.get("DKR"));
        Assert.assertEquals(new Color(0xABCDEF), colors.get("BJS"));
    }

    @Test
    public void ignoresBadLinesAndLetsLastValidLineWin()
    {
        Map<String, Color> colors = FairyRingColorService.parse(
            "not a rule\n" +
            "ZZZ, Red\n" +
            "DJR, not-a-color\n" +
            "DJR, Blue\n" +
            "DJR, #010203\n");

        Assert.assertEquals(1, colors.size());
        Assert.assertEquals(new Color(0x010203), colors.get("DJR"));
    }
}

package com.fairyringorganizer;

import org.junit.Assert;
import org.junit.Test;

public class FairyRingDestinationTest
{
    @Test
    public void acceptsValidDialCodesWithoutRequiringCatalogueEntry()
    {
        Assert.assertTrue(FairyRingDestination.isValidCode("AIP"));
        Assert.assertTrue(FairyRingDestination.isValidCode(" a i p "));
        Assert.assertFalse(FairyRingDestination.isValidCode("EIP"));
        Assert.assertFalse(FairyRingDestination.isValidCode("AIT"));
    }

    @Test
    public void resolvesKnownCodesAndLegacyDisplayAliases()
    {
        Assert.assertEquals(FairyRingDestination.DKR, FairyRingDestination.forCode("dkr"));
        Assert.assertEquals("Edgeville", FairyRingDestination.DKR.getDestination());
        Assert.assertEquals(FairyRingDestination.DKR, FairyRingDestination.forDisplayAlias("Edgeville / GE"));
        Assert.assertEquals(FairyRingDestination.DKR, FairyRingDestination.forDisplayAlias("Edgeville, Grand Exchange"));
        Assert.assertEquals(FairyRingDestination.AIQ, FairyRingDestination.forDisplayAlias("Mudskipper Point"));
    }
}

